window.AdAstraGlossarySummaries={"abbondanza-isotopica":["L’abbondanza isotopica esprime la frazione di atomi di un particolare isotopo rispetto agli atomi dello stesso elemento presenti nel campione.","lezione-3-6.html"],"aberrazione-cromatica":["Nei sistemi rifrangenti la dipendenza della rifrazione dalla lunghezza d’onda può far formare immagini di colori differenti in posizioni diverse.","lezione-7-3.html"],"aberrazione-della-luce":["Il moto dell’osservatore modifica la direzione apparente da cui riceve la luce; l’aberrazione astronomica è distinta dai difetti ottici.","lezione-1-6.html"],"aberrazione-sferica":["L’aberrazione sferica si presenta quando raggi a diverse distanze dall’asse di un sistema non convergono nello stesso fuoco nella configurazione considerata.","lezione-7-3.html"],"ablazione":["L’ablazione è la perdita di materiale da una superficie attraverso processi fisici; in astronomia è importante, per esempio, durante l’ingresso atmosferico dei meteoroidi.","lezione-8-1.html"],"accelerazione":["L’accelerazione descrive quanto cambia la velocità, intesa come vettore, nel tempo: può cambiare la rapidità, la direzione del moto o entrambe.","lezione-3-6.html"],"accrescimento":["In astrofisica l’accrescimento è l’aumento della massa di un corpo attraverso l’acquisizione di materia dall’ambiente o da una compagna.","lezione-4-5.html"],"accrescimento-ciottoli":["L’accrescimento di ciottoli è un meccanismo di crescita planetaria nel quale piccoli solidi interagiscono con gas e gravità e possono essere catturati da un corpo in formazione.","lezione-3-6.html"],"accuratezza-misura":["Nel lessico metrologico l’accuratezza riguarda la vicinanza di un valore misurato al valore vero della grandezza; va distinta dalla sola concordanza tra misure ripetute.","lezione-9-4.html"],"acetilene":["L’acetilene, nome comune dell’etino, è l’idrocarburo di formula C₂H₂ con un triplo legame tra i due atomi di carbonio.","lezione-10-2.html"],"acetonitrile":["L’acetonitrile, o cianuro di metile, è una molecola di formula CH₃CN appartenente ai nitrili. Le sue transizioni sono usate anche nello studio di ambienti astronomici.","lezione-10-2.html"],"acido-carbossilico":["Un acido carbossilico è un composto organico che contiene il gruppo carbossilico, formato da carbonile e ossidrile collegati allo stesso carbonio.","lezione-10-2.html"],"acido-cianidrico":["L’acido cianidrico, o cianuro di idrogeno, ha formula HCN. Le sue firme spettroscopiche permettono di studiare gas molecolare anche in comete e ambienti interstellari.","lezione-3-5.html"],"acqua":["L’acqua è il composto H₂O: ogni molecola comprende due atomi di idrogeno e uno di ossigeno; lo stato fisico dipende dalle condizioni ambientali.","lezione-10-2.html"],"acromatico":["Un sistema acromatico è progettato per ridurre l’aberrazione cromatica, facendo coincidere opportunamente il fuoco di determinate lunghezze d’onda.","lezione-7-3.html"],"adattamento-al-buio":["L’occhio diventa progressivamente più sensibile alla luce debole quando rimane in un ambiente poco illuminato: questo processo è l’adattamento al buio.","lezione-7-1.html"],"adsorbimento":["L’adsorbimento è il trattenimento di particelle sulla superficie di un materiale; in astrochimica collega il gas ai grani di polvere e ai loro rivestimenti.","lezione-5-4.html"],"aerofrenaggio":["L’aerofrenaggio usa il passaggio controllato negli strati alti di un’atmosfera per ridurre l’energia orbitale di un veicolo attraverso la resistenza del gas.","lezione-10-5.html"],"afelio":["L’afelio è il punto di un’orbita attorno al Sole in cui la distanza dal Sole è massima.","lezione-3-6.html"],"affinita-elettronica":["L’affinità elettronica descrive il bilancio energetico collegato all’aggiunta di un elettrone a una specie isolata; la convenzione di segno deve essere dichiarata quando si confrontano valori.","lezione-5-4.html"],"afocale":["Un sistema afocale trasforma un fascio parallelo in un altro fascio parallelo; nella fotografia afocale una fotocamera con obiettivo riprende attraverso l’oculare.","astrofotografia.html"],"airglow":["L’airglow è una debole emissione naturale dell’atmosfera, presente anche quando non si osserva un’aurora.","lezione-8-3.html"],"alanina":["L’alfa-alanina è un amminoacido di formula CH₃CH(NH₂)COOH, presente nelle proteine. La sua struttura permette di collegare nomenclatura, isomeria e chiralità.","lezione-10-2.html"],"albedo":["L’albedo descrive la capacità di un corpo o di una superficie di riflettere la radiazione, secondo una definizione e una banda da specificare.","lezione-3-2.html"],"alcol":["Gli alcoli sono composti nei quali un gruppo ossidrilico è legato a un carbonio saturo secondo la definizione della famiglia organica.","lezione-10-2.html"],"aldeide":["Un’aldeide è un composto caratterizzato da un gruppo carbonilico il cui carbonio è legato anche a un idrogeno.","lezione-10-2.html"],"allargamento-doppler":["L’allargamento Doppler è l’aumento della larghezza osservata di una riga dovuto a una distribuzione di velocità lungo la linea di vista.","lezione-4-3.html"],"alluminio":["L’alluminio è l’elemento di numero atomico 13, simbolo Al. Oltre all’impiego nei materiali, alcuni suoi isotopi aiutano a studiare la storia iniziale del Sistema solare.","lezione-3-6.html"],"almucantarat":["Un almucantarat è un cerchio di uguale altezza sulla sfera celeste locale: tutti i suoi punti hanno la stessa altezza rispetto all’orizzonte.","lezione-1-6.html"],"alogeno":["Gli alogeni sono gli elementi del gruppo 17 della tavola periodica, fra i quali fluoro, cloro, bromo e iodio.","lezione-10-2.html"],"alpher-ralph":["Ralph Alpher (1921–2007) fu un fisico importante per lo sviluppo dei primi modelli di nucleosintesi cosmologica e per la previsione di una radiazione residua dell’Universo caldo.","lezione-6-5.html"],"altezza-angolare":["Angolo fra la direzione di un astro e il piano dell’orizzonte locale. Si misura in gradi, non in metri.","lezione-1-1.html"],"altitudine":["L’altitudine è la quota di un luogo rispetto al livello medio del mare; non è l’altezza angolare di un astro sopra l’orizzonte.","lezione-7-6.html"],"ammasso-aperto":["Gruppo fisico di stelle con una distribuzione generalmente meno concentrata di quella di un ammasso globulare.","lezione-5-2.html"],"ammasso-di-galassie":["Un ammasso di galassie è una grande struttura gravitazionale che comprende numerose galassie, gas caldo e materia oscura.","lezione-6-4.html"],"ammasso-globulare":["Sistema stellare denso, approssimativamente sferoidale, con forte concentrazione di stelle verso il centro.","lezione-5-3.html"],"amminoacido":["Un amminoacido è un composto organico che possiede funzioni amminica e carbossilica; gli amminoacidi che costituiscono le proteine sono una famiglia particolarmente importante.","lezione-10-2.html"],"ammoniaca":["L’ammoniaca è la molecola NH₃, costituita da un atomo di azoto e tre di idrogeno, osservata anche in ambienti astronomici.","lezione-3-3.html"],"ampere":["L’ampere, simbolo A, è l’unità SI dell’intensità di corrente elettrica; un ampere corrisponde al passaggio netto di un coulomb al secondo.","strumentazione.html"],"ampiezza":["L’ampiezza quantifica l’entità di una variazione o oscillazione; bisogna dichiarare se indica lo scostamento dal valore centrale oppure la differenza fra massimo e minimo.","lezione-4-2.html"],"amplitudine-ortiva-e-occasa":["Distanza angolare lungo l’orizzonte fra il punto in cui un astro sorge e l’est, oppure fra il punto in cui tramonta e l’ovest.","lezione-1-5.html"],"anello-planetario":["Un anello planetario è un insieme di particelle che orbitano attorno a un pianeta, non una lastra solida fissata al suo equatore.","lezione-3-4.html"],"angolo-orario":["L’angolo orario esprime quanto una direzione celeste si trova a est o a ovest del meridiano locale, secondo la convenzione adottata.","lezione-1-3.html"],"anidride-carbonica":["L’anidride carbonica, o diossido di carbonio, è la molecola CO₂, composta da un atomo di carbonio e due di ossigeno.","lezione-3-2.html"],"anione":["Un anione è uno ione con carica elettrica negativa, associata a un eccesso di elettroni rispetto alla corrispondente specie neutra.","lezione-4-3.html"],"annichilazione":["L’annichilazione è un’interazione fra una particella e la corrispondente antiparticella nella quale lo stato iniziale viene trasformato in altre particelle.","lezione-10-3.html"],"anno-anomalistico":["Intervallo medio fra due passaggi consecutivi della Terra al perielio, pari a circa 365,26 giorni.","lezione-3-6.html"],"anno-draconico":["Intervallo medio fra due passaggi del Sole apparente per lo stesso nodo dell’orbita lunare, circa 346,62 giorni.","lezione-2-6.html"],"anno-giuliano":["L’anno giuliano astronomico è un intervallo convenzionale di 365,25 giorni, ciascuno di 86.400 secondi, usato per esprimere durate e altre grandezze.","lezione-2-1.html"],"anno-luce":["Unità di distanza: il cammino percorso dalla luce nel vuoto durante un anno.","lezione-6-3.html"],"anno-siderale":["L’anno siderale descrive il periodo della rivoluzione terrestre rispetto a un riferimento legato alle stelle lontane: circa 365 giorni, 6 ore e 9 minuti.","lezione-2-1.html"],"anno-tropico":["L’anno tropico collega il moto apparente del Sole al ciclo delle stagioni; il suo valore medio è circa 365,2422 giorni.","lezione-2-2.html"],"antimateria":["L’antimateria è costituita da antiparticelle, con massa uguale a quella delle corrispondenti particelle e valori opposti per alcune proprietà, come la carica elettrica.","lezione-10-3.html"],"apertura":["Nell’uso astronomico comune l’apertura indica il diametro utile che raccoglie luce; non va confusa con focale e ingrandimento.","lezione-7-3.html"],"apocromatico":["Un obiettivo apocromatico mira a una correzione cromatica più estesa rispetto a un acromatico classico, con proprietà da verificare nel progetto concreto.","lezione-7-3.html"],"apogeo":["L’apogeo è il punto di un’orbita geocentrica in cui il corpo si trova alla massima distanza dalla Terra.","lezione-2-4.html"],"apollo-11":["Apollo 11 fu la missione NASA che realizzò il primo allunaggio con equipaggio umano, con il modulo Eagle posato sulla Luna il 20 luglio 1969.","lezione-10-5.html"],"apside":["In un’orbita ellittica i due apsidi sono i punti di minima e massima distanza dal fuoco occupato dal corpo centrale nel modello a due corpi.","lezione-3-6.html"],"arco-diurno":["Parte della traiettoria apparente di un astro che si trova sopra l’orizzonte nel corso del suo moto diurno.","lezione-1-3.html"],"argon":["L’argon, o argo, è il gas nobile di numero atomico 18 e simbolo Ar. Le sue abbondanze isotopiche sono utili nello studio dell’evoluzione delle atmosfere e della storia delle rocce.","lezione-3-2.html"],"aristarco-samo":["Aristarco di Samo fu un astronomo e matematico greco del III secolo a.C., noto per un’ipotesi eliocentrica e per lo studio geometrico delle dimensioni e distanze di Sole e Luna.","lezione-1-3.html"],"aromaticita":["L’aromaticità è una proprietà elettronica di determinati sistemi ciclici con elettroni delocalizzati, legata a stabilità e comportamento caratteristici.","lezione-10-2.html"],"artemis":["Programma NASA per l’esplorazione lunare con equipaggio, anche in preparazione di future missioni verso Marte.","lezione-3-4.html"],"artemis-i":["Volo di prova senza equipaggio che nel 2022 portò Orion attorno alla Luna.","lezione-3-4.html"],"artemis-ii":["Missione con equipaggio del programma Artemis dedicata al sorvolo della Luna.","lezione-3-4.html"],"ascensione-retta":["Coordinata equatoriale che individua la posizione lungo l’equatore celeste, con origine nel punto equinoziale di primavera.","lezione-1-6.html"],"assetto-spaziale":["L’assetto è l’orientamento di un veicolo spaziale rispetto a un sistema di riferimento. È distinto dalla posizione e dalla traiettoria del veicolo.","lezione-10-5.html"],"assistenza-gravitazionale":["L’assistenza gravitazionale usa l’incontro con un corpo celeste in moto per modificare la traiettoria e l’energia orbitale di una sonda rispetto al riferimento considerato.","lezione-10-5.html"],"asterismo":["Un asterismo è una figura riconoscibile formata da stelle viste in una certa disposizione apparente; può occupare parte di una costellazione o attraversarne più di una.","lezione-1-4.html"],"asteroide":["Gli asteroidi sono piccoli corpi del Sistema solare, prevalentemente rocciosi o metallici, con proprietà e orbite molto diverse.","lezione-3-5.html"],"asterosismologia":["L’asterosismologia usa le oscillazioni delle stelle per studiarne proprietà e struttura interna.","lezione-4-1.html"],"astrobiologia":["L’astrobiologia studia l’origine, l’evoluzione e la possibile distribuzione della vita nell’Universo, collegando biologia, geologia, chimica e astronomia.","lezione-10-2.html"],"astrochimica":["L’astrochimica studia composizione, formazione e trasformazione delle specie chimiche negli ambienti astronomici, collegando osservazioni, esperimenti di laboratorio e modelli.","lezione-10-2.html"],"astrofotografia":["L’astrofotografia comprende tecniche di ripresa ed elaborazione che registrano la luce degli oggetti e dei fenomeni astronomici.","astrofotografia.html"],"astroinseguitore":["Un astroinseguitore fotografico compensa il moto diurno con una rotazione attorno a un asse disposto parallelamente a quello terrestre.","lezione-7-3.html"],"astrometria":["L’astrometria misura posizioni e movimenti dei corpi celesti in sistemi di riferimento definiti.","lezione-9-4.html"],"astronomia":["L’astronomia studia i corpi e i fenomeni celesti attraverso osservazioni, modelli e confronto delle loro proprietà ed evoluzione.","lezione-1-1.html"],"atmosfera":["L’atmosfera è l’involucro gassoso di un corpo; in astronomia osservativa è anche il mezzo attraverso cui riceviamo gran parte dei segnali dal cielo.","lezione-8-4.html"],"atomo":["Un atomo è una struttura composta da un nucleo e da elettroni; il numero di protoni identifica l’elemento chimico.","lezione-4-3.html"],"attinoide":["Gli attinoidi sono la serie di elementi dall’attinio al laurenzio, con numeri atomici da 89 a 103; tutti possiedono soltanto isotopi radioattivi.","lezione-10-4.html"],"attivita-solare":["L’attività solare comprende fenomeni legati soprattutto all’evoluzione del campo magnetico del Sole, come macchie, brillamenti ed espulsioni di materiale.","lezione-2-3.html"],"aurora-polare":["L’aurora è un’emissione dell’alta atmosfera prodotta dall’interazione con particelle energetiche, collegata alla dinamica dell’ambiente magnetico terrestre.","lezione-8-3.html"],"autoguida":["In astrofotografia l’autoguida misura gli spostamenti di una stella o di un campo e invia correzioni alla montatura per ridurre gli errori di inseguimento.","astrofotografia.html"],"avogadro-amedeo":["Amedeo Avogadro (1776–1856) fu un fisico italiano importante per la distinzione fra atomi e molecole e per lo studio dei gas.","lezione-10-2.html"],"azimut":["Coordinata che indica la direzione sul piano dell’orizzonte. Va sempre dichiarata la convenzione di origine e verso.","lezione-1-6.html"],"azoto":["L’azoto è l’elemento chimico di numero atomico 7 e simbolo N; la molecola N₂ costituisce la maggior parte dell’aria terrestre secca.","lezione-3-3.html"],"backlash":["Il backlash è il gioco che può produrre una risposta ritardata quando una trasmissione meccanica inverte il verso del movimento.","strumentazione.html"],"banda-fotometrica":["Una banda fotometrica identifica una risposta spettrale definita entro cui si misura la luce di un oggetto astronomico.","lezione-4-3.html"],"banda-molecolare":["Una banda molecolare è un insieme di righe spettroscopiche ravvicinate associate a transizioni di una molecola, che può apparire come una regione estesa di emissione o assorbimento.","lezione-4-3.html"],"banda-passante":["La banda passante è l’intervallo spettrale o di frequenze che un dispositivo lascia passare secondo una risposta e un criterio di misura dichiarati.","astrofotografia.html"],"baricentro":["In astronomia il baricentro viene usato come centro di massa del sistema: la sua posizione dipende dalla distribuzione delle masse.","lezione-3-6.html"],"bario":["Il bario è l’elemento chimico di simbolo Ba e numero atomico 56, un metallo alcalino-terroso. Le sue abbondanze stellari possono offrire indizi sui processi di arricchimento chimico.","lezione-4-6.html"],"barlow":["La lente di Barlow è un accessorio ottico che aumenta la focale equivalente del sistema e, nell’uso visuale con lo stesso oculare, l’ingrandimento.","lezione-7-4.html"],"basalto":["Il basalto è una roccia magmatica effusiva, generalmente scura e relativamente povera di silice, con minerali come plagioclasi e pirosseni.","lezione-3-2.html"],"bayer-designazione":["La designazione di Bayer identifica molte stelle con una lettera, spesso greca, associata al nome latino della costellazione nella forma grammaticale prevista.","lezione-9-4.html"],"becquerel-unita":["Il becquerel, simbolo Bq, è l’unità SI dell’attività radioattiva: un becquerel corrisponde a una trasformazione nucleare al secondo, intesa come tasso statistico.","lezione-10-4.html"],"bepicolombo":["BepiColombo è una missione ESA e JAXA destinata allo studio di Mercurio, mediante due veicoli scientifici con compiti complementari sul pianeta e sul suo ambiente magnetico.","lezione-3-2.html"],"berillio":["Il berillio è l’elemento di numero atomico 4, simbolo Be. È interessante sia per la storia degli elementi leggeri sia per materiali impiegati nella strumentazione spaziale.","lezione-10-5.html"],"bethe-hans":["Hans Bethe (1906–2005) fu un fisico che contribuì alla teoria delle reazioni nucleari e alla comprensione della produzione di energia nelle stelle.","lezione-4-1.html"],"bias":["Nella calibrazione delle immagini astronomiche, un fotogramma di bias caratterizza il livello elettronico di riferimento e la struttura associata alla lettura, senza segnale luminoso del soggetto.","astrofotografia.html"],"big-bang":["Il modello del Big Bang descrive l’evoluzione dell’Universo da una fase molto calda e densa, seguita da espansione e raffreddamento.","lezione-6-5.html"],"bilanciamento":["Il bilanciamento distribuisce il carico rispetto agli assi della montatura per limitarne gli squilibri, secondo le indicazioni previste per quel sistema.","strumentazione.html"],"binaria-a-eclisse":["Una binaria a eclisse è un sistema di due stelle la cui geometria consente occultazioni reciproche apparenti, producendo variazioni periodiche della luce ricevuta.","lezione-4-1.html"],"binaria-astrometrica":["Una binaria astrometrica è studiata attraverso il movimento apparente di una componente o del centro di luce che segnala l’influenza orbitale di una compagna.","lezione-4-1.html"],"binaria-spettroscopica":["Una binaria spettroscopica viene riconosciuta o studiata attraverso variazioni delle righe spettrali associate al moto orbitale delle componenti.","lezione-4-3.html"],"binaria-visuale":["Una binaria visuale è un sistema stellare fisicamente legato nel quale le componenti possono essere risolte come sorgenti separate con osservazioni adatte.","lezione-4-1.html"],"binning":["Il binning combina misure di pixel vicini in elementi più grandi, riducendo il numero di campioni dell’immagine; il modo in cui avviene dipende da camera e software.","astrofotografia.html"],"binocolo":["Un binocolo usa due canali ottici accoppiati per osservare con entrambi gli occhi immagini ingrandite e raddrizzate.","lezione-7-2.html"],"binocolo-porro":["Un binocolo a prismi di Porro usa una disposizione di prismi per raddrizzare l’immagine e ripiegare il percorso ottico, spesso con obiettivi e oculari lateralmente sfalsati.","lezione-7-2.html"],"binocolo-tetto":["Un binocolo a prismi a tetto impiega sistemi prismatici con superfici disposte secondo una geometria detta a tetto, spesso in una struttura esterna più allineata e compatta.","lezione-7-2.html"],"blazar":["Un blazar è un nucleo galattico attivo nel quale osserviamo un getto relativistico orientato vicino alla nostra linea di vista, con emissione spesso intensa e variabile.","lezione-6-2.html"],"bohr-niels":["Niels Bohr (1885–1962) contribuì alla descrizione quantistica dell’atomo e all’interpretazione degli spettri, proponendo nel 1913 un modello particolarmente efficace per l’idrogeno.","lezione-4-3.html"],"bolide":["Un bolide è una meteora particolarmente vistosa; l’uso del termine e le soglie adottate possono variare fra contesti osservativi.","lezione-8-1.html"],"bolometria":["La bolometria usa il riscaldamento prodotto dall’assorbimento di radiazione per ricavarne una misura. Il rivelatore, chiamato bolometro, trasforma una piccola variazione termica in un segnale misurabile.","lezione-4-3.html"],"bolometro":["Un bolometro è un rivelatore che misura radiazione attraverso l’effetto termico prodotto dall’energia assorbita.","lezione-4-3.html"],"bordo-lunare":["Il bordo lunare è il contorno apparente del disco della Luna contro il cielo, la cui forma dettagliata dipende anche dai rilievi e dalla prospettiva.","lezione-2-5.html"],"boro":["Il boro è l’elemento di numero atomico 5, simbolo B. La sua presenza cosmica contribuisce allo studio della produzione e trasformazione degli elementi leggeri.","lezione-4-6.html"],"bosone":["Un bosone è una particella di spin intero o nullo che segue la statistica di Bose–Einstein, con un comportamento differente da quello dei fermioni identici.","lezione-4-3.html"],"boyle-robert":["Robert Boyle (1627–1691) fu un filosofo naturale e sperimentatore, importante per lo studio dei gas e per lo sviluppo della chimica.","lezione-3-3.html"],"brahe-tycho":["Tycho Brahe (1546–1601) fu un astronomo danese le cui misure sistematiche, anteriori all’astronomia telescopica, furono decisive per lo studio delle orbite planetarie.","lezione-9-4.html"],"bremsstrahlung":["La bremsstrahlung, o radiazione di frenamento, è emissione elettromagnetica associata all’accelerazione di particelle cariche nel campo di altre particelle.","lezione-10-3.html"],"brillamento-solare":["Un brillamento solare è una rapida liberazione di energia nell’atmosfera del Sole che produce un aumento dell’emissione elettromagnetica.","lezione-2-3.html"],"brillanza-superficiale":["La brillanza superficiale descrive quanto segnale riceviamo per una certa area apparente di un oggetto esteso, nella banda considerata.","lezione-5-1.html"],"brinamento":["Il brinamento è il passaggio diretto dalla fase gassosa alla fase solida; è il processo inverso della sublimazione.","lezione-7-6.html"],"buco-coronale":["Un buco coronale è una regione della corona solare relativamente meno densa e meno emissiva in determinate bande, associata a configurazioni magnetiche aperte e a vento solare veloce.","lezione-2-3.html"],"buco-nero":["Un buco nero è una regione dello spaziotempo delimitata da un orizzonte degli eventi, dal cui interno nessun segnale può raggiungere osservatori esterni lontani.","lezione-10-3.html"],"burbidge-margaret":["Margaret Burbidge (1919–2020) fu un’astronoma e astrofisica importante per la spettroscopia e per lo studio della formazione degli elementi nelle stelle.","lezione-4-6.html"],"calcio":["Il calcio è l’elemento di numero atomico 20 e simbolo Ca, presente nei minerali e studiato attraverso importanti righe spettrali atomiche e ioniche.","lezione-2-3.html"],"calendario":["Un calendario organizza i giorni e gli anni secondo regole civili o culturali, spesso costruite per mantenere un rapporto con cicli astronomici.","lezione-2-1.html"],"calibrazione":["La calibrazione collega una misura alla risposta dello strumento e ai riferimenti necessari per interpretarla; nelle immagini astronomiche comprende correzioni strumentali documentate.","astrofotografia.html"],"callisto":["Callisto è un satellite galileiano di Giove con una superficie antica e fortemente craterizzata.","lezione-3-4.html"],"calore":["Il calore è energia trasferita fra sistemi a causa di una differenza di temperatura. Non è una sostanza contenuta nei corpi né un sinonimo della temperatura.","lezione-2-3.html"],"calore-latente":["Il calore latente specifico è l’energia scambiata per unità di massa durante una transizione di fase nelle condizioni dichiarate.","lezione-3-5.html"],"calore-specifico":["Il calore specifico indica quanta energia termica occorre per aumentare di un kelvin la temperatura dell’unità di massa di una sostanza, nelle condizioni specificate.","lezione-3-2.html"],"cammino-libero-medio":["Il cammino libero medio è la distanza media percorsa da una particella o da un fotone fra interazioni del tipo specificato, nelle condizioni del mezzo considerato.","lezione-2-3.html"],"campionamento":["Nelle immagini astronomiche il campionamento descrive come il segnale viene rappresentato da misure discrete; la scala d’immagine indica quanto angolo corrisponde a ciascun pixel.","astrofotografia.html"],"campione-statistico":["Un campione statistico è un insieme di elementi o misure utilizzato per studiare una popolazione o un processo.","lezione-9-4.html"],"campo-apparente":["Il campo apparente di un oculare è l’ampiezza angolare sotto cui si presenta il suo campo visivo all’occhio, distinta dalla porzione reale di cielo inquadrata.","lezione-7-4.html"],"campo-elettrico":["Il campo elettrico descrive la forza elettrica per unità di carica positiva di prova in ogni punto; è una grandezza vettoriale.","lezione-8-3.html"],"campo-magnetico":["Il campo magnetico descrive proprietà fisiche che determinano azioni su cariche in movimento, correnti e momenti magnetici.","lezione-2-3.html"],"campo-reale":["Il campo reale è l’estensione angolare della porzione di cielo compresa nell’inquadratura di uno strumento in una certa configurazione.","lezione-7-4.html"],"canali-marziani":["I canali marziani erano strutture lineari riportate in osservazioni e carte storiche di Marte; la loro interpretazione come rete geometrica artificiale è stata superata.","lezione-3-2.html"],"candela-unita":["La candela, simbolo cd, è l’unità SI dell’intensità luminosa in una determinata direzione, secondo la convenzione fotometrica specificata.","lezione-7-5.html"],"cannocchiale-polare":["Il cannocchiale polare è un piccolo sistema ottico con reticolo che aiuta ad allineare l’asse di ascensione retta di una montatura al polo celeste.","strumentazione.html"],"cannon-annie":["Annie Jump Cannon (1863–1941) fu un’astronoma statunitense il cui lavoro sistematico sugli spettri ebbe un ruolo centrale nella classificazione stellare di Harvard.","lezione-4-4.html"],"capacita-elettrica":["La capacità elettrica esprime il rapporto fra carica e potenziale, o differenza di potenziale, per un sistema definito. Nel Sistema Internazionale si misura in farad.","strumentazione.html"],"carbonato":["I carbonati sono composti che contengono il gruppo carbonato CO₃²⁻; molti costituiscono minerali e rocce importanti per la storia chimica dei pianeti.","lezione-3-2.html"],"carbonio":["Il carbonio è l’elemento chimico di numero atomico 6 e simbolo C, capace di formare una grande varietà di strutture e composti.","lezione-10-2.html"],"carica-elettrica":["La carica elettrica è una proprietà della materia coinvolta nell’interazione elettromagnetica. Può avere segno positivo o negativo e si misura in coulomb.","lezione-4-3.html"],"caronte":["Caronte è il maggiore satellite di Plutone e forma con esso un sistema nel quale il baricentro si trova all’esterno dei due corpi.","lezione-3-5.html"],"cassini":["Cassini fu l’orbiter della missione internazionale Cassini–Huygens: studiò Saturno e il suo sistema dal 2004 al 2017, dopo il lancio del 1997.","lezione-3-4.html"],"catadiottrico":["Un sistema ottico catadiottrico combina superfici riflettenti e rifrangenti nella formazione o nella correzione dell’immagine.","lezione-7-3.html"],"catalisi":["La catalisi modifica la velocità di una reazione attraverso un percorso che coinvolge un catalizzatore, rigenerato nel ciclo complessivo, senza spostare l’equilibrio termodinamico.","lezione-5-4.html"],"catalogo-astronomico":["Un catalogo astronomico raccoglie dati strutturati su sorgenti celesti, con identificatori, misure e informazioni necessarie a interpretarli.","lezione-9-4.html"],"catena-protone-protone":["La catena protone–protone è un insieme di reazioni nucleari che converte complessivamente idrogeno in elio ed è la principale sorgente di energia nucleare del Sole.","lezione-2-3.html"],"catione":["Un catione è uno ione con carica elettrica positiva, perché possiede meno elettroni della corrispondente specie neutra nel confronto appropriato.","lezione-4-3.html"],"cattura-elettronica-nucleare":["La cattura elettronica nucleare è una trasformazione nella quale il nucleo assorbe un elettrone e un protone diventa un neutrone, con emissione di un neutrino elettronico.","lezione-10-4.html"],"cattura-neutronica":["La cattura neutronica è una reazione nella quale un nucleo incorpora un neutrone; nel caso della cattura radiativa il nucleo risultante emette radiazione per perdere l’energia di eccitazione.","lezione-10-4.html"],"ccd":["Un CCD è un dispositivo a trasferimento di carica; nei sensori d’immagine raccoglie segnali elettrici prodotti dalla luce e li trasferisce per la lettura.","astrofotografia.html"],"cefeide":["Una Cefeide è una stella variabile pulsante la cui relazione fra periodo e luminosità, opportunamente calibrata, permette di stimare distanze astronomiche.","lezione-6-3.html"],"cerchio-massimo":["Un cerchio massimo si ottiene intersecando una sfera con un piano che passa per il suo centro. Sulla superficie ne consideriamo la circonferenza.","lezione-1-6.html"],"cerere":["Cerere è un pianeta nano della fascia principale degli asteroidi, esplorato in orbita dalla missione Dawn.","lezione-3-5.html"],"chandra":["Chandra è un osservatorio spaziale della NASA, lanciato nel 1999, progettato per studiare l’Universo attraverso i raggi X. ","lezione-10-5.html"],"chandrasekhar-subrahmanyan":["Subrahmanyan Chandrasekhar (1910–1995) fu un astrofisico di origine indiana, Nobel per la fisica nel 1983 per studi teorici fondamentali sulla struttura e sull’evoluzione stellare.","lezione-4-6.html"],"chetone":["Un chetone è un composto nel quale il carbonio di un gruppo carbonilico è legato a due gruppi carboniosi.","lezione-10-2.html"],"chilogrammo":["Il chilogrammo, simbolo kg, è l’unità SI della massa; dal 2019 la sua definizione si basa sul valore fissato della costante di Planck.","lezione-4-1.html"],"chiralita":["La chiralità è la proprietà di una struttura che non può essere sovrapposta alla propria immagine speculare, come accade alle due mani.","lezione-10-2.html"],"ciclo-cno":["Il ciclo CNO è una rete di reazioni nucleari che trasforma idrogeno in elio usando nuclei di carbonio, azoto e ossigeno come intermedi del ciclo.","lezione-4-1.html"],"ciclo-solare":["Il ciclo solare descrive la variazione quasi periodica dell’attività magnetica del Sole, evidente anche nel numero delle macchie.","lezione-2-3.html"],"cifre-significative":["Le cifre significative esprimono l’informazione numerica che si intende conservare in un valore approssimato, in rapporto alla precisione e al contesto della misura.","lezione-9-4.html"],"cinetica-chimica":["La cinetica chimica studia le velocità delle reazioni e i meccanismi attraverso i quali reagenti e intermedi si trasformano in prodotti.","lezione-5-4.html"],"circumpolare":["Detto di un astro che, da una determinata latitudine, non scende mai sotto l’orizzonte nel moto diurno.","lezione-1-3.html"],"classe-spettrale":["La classe spettrale raggruppa stelle con caratteristiche simili dello spettro; nella sequenza principale di classificazione queste caratteristiche sono fortemente collegate alla temperatura superficiale.","lezione-4-3.html"],"clatrato":["Un clatrato è un composto di inclusione nel quale una struttura ospitante racchiude altre specie; nei clatrati idrati la rete ospitante è formata da acqua.","lezione-3-4.html"],"cloro":["Il cloro è l’elemento di numero atomico 17, simbolo Cl, appartenente agli alogeni. I suoi composti e isotopi contribuiscono allo studio della chimica dei materiali planetari.","lezione-3-2.html"],"cmos":["CMOS indica una tecnologia elettronica; nei sensori fotografici è associata ad architetture di raccolta e lettura del segnale luminoso differenti da quelle dei CCD.","astrofotografia.html"],"cobalto":["Il cobalto è l’elemento chimico di simbolo Co e numero atomico 27; alcuni suoi isotopi radioattivi partecipano alla storia energetica delle supernovae.","lezione-10-4.html"],"coda-cometaria":["Una coda cometaria è una struttura di materiale disperso dalla cometa, modellata da radiazione solare, vento solare e moto dei granuli.","lezione-3-5.html"],"collimazione":["Nell’uso dei telescopi la collimazione è la regolazione dell’allineamento degli elementi ottici e dei riferimenti del sistema.","lezione-7-3.html"],"coma-cometaria":["La coma, o chioma, è l’inviluppo diffuso di gas e polveri che si sviluppa attorno al nucleo di una cometa attiva.","lezione-3-5.html"],"coma-ottica":["La coma è un’aberrazione che può rendere asimmetrica e simile a una piccola chioma l’immagine di una sorgente fuori asse.","lezione-7-3.html"],"cometa":["Corpo del Sistema solare che può sviluppare una chioma e code quando la sua attività libera gas e polveri.","lezione-3-5.html"],"componenti-vettore":["Le componenti di un vettore sono i valori che lo descrivono rispetto alle direzioni di una base scelta.","lezione-1-6.html"],"concentrazione-molare":["La concentrazione molare è la quantità di sostanza di un componente divisa per il volume della soluzione. È spesso espressa in moli per litro.","lezione-10-2.html"],"condensa":["La condensazione trasforma vapore in liquido; durante un’osservazione può formare goccioline sulle superfici ottiche raffreddate.","lezione-7-6.html"],"conducibilita-elettrica":["La conducibilità elettrica descrive quanto un materiale risponda con una corrente all’azione di un campo elettrico. Nel caso lineare isotropo è l’inverso della resistività.","lezione-8-3.html"],"conduzione-termica":["La conduzione termica è un trasferimento di energia nella materia associato a differenze di temperatura, senza trasporto macroscopico del materiale come nella convezione.","lezione-7-6.html"],"configurazione-elettronica":["La configurazione elettronica indica l’occupazione degli orbitali da parte degli elettroni in un modello della struttura atomica o molecolare.","lezione-4-3.html"],"congiunzione":["Una congiunzione è una configurazione di coordinate apparenti: due astri condividono una coordinata specificata, senza trovarsi necessariamente vicini nello spazio.","lezione-9-3.html"],"conservazione-energia":["La conservazione dell’energia afferma che l’energia totale di un sistema isolato resta costante, pur potendo essere trasferita o trasformata fra forme differenti.","lezione-3-6.html"],"conservazione-quantita-moto":["La quantità di moto totale di un sistema rimane costante quando è nulla la risultante delle forze esterne, nel quadro classico considerato.","lezione-3-6.html"],"contrappeso":["Un contrappeso è una massa collocata per compensare il momento prodotto da altri componenti rispetto a un asse di rotazione.","strumentazione.html"],"contrasto":["Il contrasto descrive quanto una struttura si distingue dal fondo o dalle regioni vicine in un’immagine o nella percezione visiva.","lezione-7-5.html"],"convertitore-analogico-digitale":["Un convertitore analogico-digitale trasforma un segnale analogico in valori numerici che possono essere memorizzati ed elaborati da un sistema digitale.","astrofotografia.html"],"convezione":["La convezione trasporta energia attraverso movimenti di materia. È importante nelle stelle, nelle atmosfere e in molti ambienti planetari.","lezione-4-1.html"],"coordinate-altazimutali":["Altezza e azimut individuano una direzione rispetto alla verticale e all’orizzonte del luogo di osservazione.","lezione-1-6.html"],"coordinate-eclittiche":["Longitudine e latitudine eclittiche descrivono direzioni rispetto al piano dell’eclittica e alla sua origine convenzionale.","lezione-1-6.html"],"coordinate-equatoriali":["Ascensione retta e declinazione descrivono direzioni usando equatore e poli celesti come riferimenti.","lezione-1-6.html"],"coordinate-galattiche":["Le coordinate galattiche descrivono direzioni riferite al piano convenzionale della Via Lattea, attraverso longitudine e latitudine galattiche.","lezione-6-1.html"],"coordinate-geocentriche":["Le coordinate geocentriche riferiscono una posizione al centro della Terra, con assi e convenzioni da specificare.","lezione-1-6.html"],"coordinate-topocentriche":["Le coordinate topocentriche descrivono una posizione riferita a uno specifico osservatore o punto della superficie terrestre.","lezione-1-6.html"],"copernico-niccolo":["Niccolò Copernico (1473–1543) sviluppò un modello astronomico nel quale la Terra ruota su sé stessa e partecipa al moto dei pianeti attorno al Sole.","lezione-1-3.html"],"corona-solare":["La corona è la regione più esterna dell’atmosfera solare, costituita da plasma rarefatto e molto caldo, la cui struttura è fortemente legata al campo magnetico.","lezione-2-3.html"],"coronografo":["Un coronografo riduce la luce di una sorgente molto brillante per studiare strutture più deboli vicine alla sua direzione.","lezione-2-3.html"],"corpo-nero":["Il corpo nero è un modello ideale che assorbe tutta la radiazione incidente e, in equilibrio termico, emette uno spettro determinato dalla temperatura.","lezione-4-3.html"],"correlazione-statistica":["La correlazione statistica descrive un’associazione fra variazioni di grandezze, senza dimostrare da sola un rapporto di causa ed effetto.","lezione-9-4.html"],"corrente-di-buio":["La corrente di buio è il segnale generato nel rivelatore anche senza luce incidente, dovuto a processi interni del dispositivo e dipendente dalle condizioni operative.","astrofotografia.html"],"corrente-elettrica":["La corrente elettrica misura il trasferimento netto di carica attraverso una sezione nell’unità di tempo.","strumentazione.html"],"cosmologia":["La cosmologia studia l’Universo nel suo insieme: struttura su grande scala, evoluzione e proprietà fisiche. Confronta modelli teorici con osservazioni, fra cui espansione cosmica, radiazione di fondo e distribuzione delle galassie.","lezione-6-5.html"],"costante-avogadro":["La costante di Avogadro collega la quantità di sostanza al numero di entità: il suo valore SI è esattamente 6,02214076 × 10²³ per mole.","lezione-4-1.html"],"costante-gravitazionale":["La costante gravitazionale G fissa l’intensità dell’interazione nella legge newtoniana della gravitazione e viene determinata sperimentalmente.","lezione-3-6.html"],"costante-planck":["La costante di Planck, indicata con h, collega l’energia di un fotone alla sua frequenza e compare nella descrizione quantistica dei fenomeni.","lezione-4-3.html"],"costellazione":["Regione delimitata della sfera celeste, associata tradizionalmente a una figura apparente di stelle.","lezione-1-4.html"],"coulomb":["Il coulomb, simbolo C, è l’unità SI della carica elettrica; equivale alla carica trasferita da una corrente costante di un ampere in un secondo.","strumentazione.html"],"cratere-impatto":["Un cratere da impatto è una struttura prodotta dall’urto ad alta velocità di un corpo contro una superficie, con compressione, scavo e redistribuzione del materiale bersaglio.","lezione-2-5.html"],"crepuscolo":["Il crepuscolo è la fase di luminosità diffusa del cielo prima del sorgere o dopo il tramonto del Sole, mentre il Sole si trova sotto l’orizzonte.","lezione-9-5.html"],"criovolcanismo":["Il criovulcanismo indica processi eruttivi su corpi freddi nei quali materiali volatili, come acqua e miscele contenenti ghiacci, svolgono un ruolo analogo a quello dei materiali fusi nel vulcanismo roccioso.","lezione-3-4.html"],"cristallizzazione":["La cristallizzazione è la formazione di una fase solida con organizzazione ordinata a lungo raggio.","lezione-3-2.html"],"cromo":["Il cromo è l’elemento chimico di simbolo Cr e numero atomico 24, un metallo studiato anche attraverso i rapporti isotopici dei materiali del Sistema solare.","lezione-3-1.html"],"cromosfera":["La cromosfera è una regione dell’atmosfera solare situata sopra la fotosfera e sotto la regione di transizione verso la corona.","lezione-2-3.html"],"crosta-planetaria":["La crosta è l’involucro solido più esterno di un corpo roccioso differenziato, distinto per composizione e struttura dai materiali profondi.","lezione-3-2.html"],"culminazione":["La culminazione è il passaggio di un astro al meridiano locale: superiore in corrispondenza del massimo della traiettoria diurna, inferiore in corrispondenza del minimo.","lezione-1-3.html"],"curie-marie":["Marie Skłodowska Curie (1867–1934) fu una scienziata protagonista dello studio della radioattività e, con Pierre Curie e collaboratori, della scoperta di polonio e radio.","lezione-10-4.html"],"curva-di-luce":["Una curva di luce rappresenta come varia nel tempo il segnale luminoso misurato di una sorgente, in una banda e con una scala specificate.","lezione-10-1.html"],"curva-rotazione":["Una curva di rotazione galattica rappresenta la velocità di rotazione ricostruita di stelle o gas in funzione della distanza dal centro della galassia.","lezione-6-2.html"],"curvatura-campo":["La curvatura di campo è la proprietà per cui la superficie di miglior fuoco di un sistema ottico non coincide con un piano.","astrofotografia.html"],"dark-frame":["Un dark frame è una ripresa di calibrazione eseguita senza luce sul sensore, con impostazioni adatte a rappresentare il segnale strumentale presente nelle esposizioni astronomiche.","astrofotografia.html"],"datazione-radiometrica":["La datazione radiometrica stima il tempo trascorso da un evento nella storia di un materiale utilizzando trasformazioni radioattive e composizioni isotopiche misurate.","lezione-3-6.html"],"dawn":["Dawn è la missione NASA che studiò da orbite dedicate Vesta e Cerere, due corpi differenti della fascia principale degli asteroidi.","lezione-3-5.html"],"debayerizzazione":["La debayerizzazione ricostruisce un’immagine a colori a partire dalle misure di un sensore con mosaico di filtri cromatici, come una matrice Bayer.","astrofotografia.html"],"decadimento-alfa":["Il decadimento alfa è una trasformazione radioattiva nella quale un nucleo emette una particella formata da due protoni e due neutroni.","lezione-10-4.html"],"decadimento-beta":["Il decadimento beta è una trasformazione nucleare mediata dall’interazione debole, nella quale cambia il numero di protoni con emissione di un elettrone o positrone e del corrispondente antineutrino o neutrino.","lezione-10-4.html"],"declinazione":["Coordinata equatoriale che misura la distanza angolare a nord o a sud dell’equatore celeste, fra −90° e +90°.","lezione-1-6.html"],"declinazione-magnetica":["Angolo locale fra il meridiano geografico e quello magnetico.","lezione-1-2.html"],"deconvoluzione":["La deconvoluzione è una ricostruzione matematica che cerca di compensare parte della sfocatura usando un modello della risposta del sistema e ipotesi sul dato.","astrofotografia.html"],"deep-impact":["Deep Impact fu una missione NASA che nel 2005 inviò un impattatore sulla cometa Tempel 1 per studiare materiale e risposta del nucleo.","lezione-3-5.html"],"deimos":["Deimos è il minore e più esterno dei due satelliti di Marte, un piccolo corpo irregolare con superficie ricoperta da materiale fine.","lezione-3-4.html"],"densita":["La densità di massa è la massa per unità di volume; una densità media non descrive necessariamente ogni regione interna di un corpo.","lezione-3-2.html"],"densita-colonna":["La densità di colonna conta la quantità di una specie lungo una linea di vista per unità di superficie trasversale. È diversa dalla densità locale per unità di volume.","lezione-5-4.html"],"deriva-allineamento":["Il metodo della deriva stellare valuta l’allineamento polare di una montatura equatoriale osservando una tendenza del movimento delle stelle in condizioni controllate.","strumentazione.html"],"desorbimento":["Il desorbimento è il rilascio di particelle precedentemente trattenute su una superficie; può riportare nel gas molecole presenti sui grani interstellari.","lezione-5-4.html"],"deuterio":["Il deuterio è l’isotopo stabile dell’idrogeno con un protone e un neutrone nel nucleo; si indica con ²H o D.","lezione-3-6.html"],"deviazione-standard":["La deviazione standard è una misura della dispersione dei valori attorno alla media, espressa nella stessa unità della grandezza considerata.","lezione-9-4.html"],"diaframma":["Un diaframma ottico delimita un fascio di luce; in un obiettivo fotografico il diaframma di apertura regola l’apertura utile del sistema.","astrofotografia.html"],"diagonale":["Il diagonale astronomico devia il fascio verso l’oculare per rendere più comoda l’osservazione, attraverso uno specchio o un prisma appropriato.","strumentazione.html"],"diagramma-hr":["Il diagramma di Hertzsprung–Russell confronta luminosità e temperatura efficace o tipo spettrale delle stelle, permettendo di studiarne struttura ed evoluzione.","lezione-4-4.html"],"diamagnetismo":["Il diamagnetismo è una risposta della materia che produce una magnetizzazione opposta al campo magnetico applicato.","lezione-10-2.html"],"diametro-angolare":["Il diametro angolare misura l’angolo sotto cui appare l’estensione di un oggetto da un punto di osservazione. Si esprime in gradi, primi o secondi d’arco.","lezione-1-6.html"],"difetto-massa":["Il difetto di massa di un nucleo è la differenza fra la somma delle masse dei nucleoni liberi che lo compongono e la massa del nucleo legato.","lezione-4-1.html"],"diffrazione":["La natura ondulatoria della luce fa sì che un’apertura finita produca una figura estesa anche per una sorgente puntiforme.","lezione-7-3.html"],"diffusione-della-luce":["La diffusione redistribuisce la radiazione in direzioni differenti attraverso l’interazione con particelle o strutture del mezzo.","lezione-8-4.html"],"dilatazione-temporale":["La dilatazione temporale indica differenze fra durate misurate o accumulate da orologi in condizioni di moto o gravità differenti, secondo le relazioni della relatività.","lezione-10-3.html"],"dipolo-elettrico":["Un dipolo elettrico descrive una separazione di carica positiva e negativa; il suo momento misura intensità e orientamento della distribuzione. È importante anche nella spettroscopia molecolare.","lezione-5-4.html"],"dipolo-magnetico":["Un dipolo magnetico è una configurazione caratterizzata da un momento magnetico che ne descrive orientamento e intensità nell’approssimazione dipolare.","lezione-8-3.html"],"disaccoppiamento-fotoni":["Il disaccoppiamento dei fotoni è la fase in cui, nell’Universo primordiale, la radiazione cominciò a propagarsi molto più liberamente perché diminuirono le interazioni con gli elettroni liberi.","lezione-6-5.html"],"disco-di-accrescimento":["Un disco di accrescimento è una struttura di materia in orbita che trasferisce momento angolare e può alimentare un corpo centrale.","lezione-10-3.html"],"disco-di-airy":["Il disco di Airy è la regione centrale della figura di diffrazione prodotta idealmente da un’apertura circolare non ostruita quando osserva una sorgente puntiforme.","lezione-7-5.html"],"disco-protoplanetario":["Un disco protoplanetario è una struttura di gas e polveri attorno a una stella giovane, nella quale possono svilupparsi i processi che formano pianeti.","lezione-3-6.html"],"dissociazione-chimica":["La dissociazione è la separazione di una specie o di un insieme legato in costituenti più semplici, molecolari, atomici o ionici secondo il processo.","lezione-10-2.html"],"distanza-angolare":["La distanza angolare fra due direzioni celesti è l’angolo che esse formano per un osservatore, misurato lungo l’arco più breve della sfera celeste.","lezione-1-4.html"],"distanza-comovente":["La distanza comovente è una misura cosmologica definita su coordinate che separano il contributo dell’espansione media dal moto delle sorgenti.","lezione-6-5.html"],"distanza-di-luminosita":["La distanza di luminosità è la distanza definita collegando luminosità intrinseca e flusso osservato con la forma della legge dell’inverso del quadrato, nel modello adottato.","lezione-6-5.html"],"distanza-zenitale":["La distanza zenitale è l’angolo fra la direzione dello zenit e quella di un astro, misurato lungo il cerchio verticale che li unisce.","lezione-1-6.html"],"distribuzione-normale":["La distribuzione normale, o gaussiana, è una distribuzione continua simmetrica a campana, determinata da media e deviazione standard.","lezione-9-4.html"],"distribuzione-probabilita":["Una distribuzione di probabilità descrive come la probabilità si ripartisce fra i possibili risultati di una variabile.","lezione-9-4.html"],"dithering":["In astrofotografia il dithering consiste nel cambiare leggermente l’inquadratura fra esposizioni, per spostare le immagini celesti su pixel differenti del sensore.","astrofotografia.html"],"dobson":["Una montatura dobsoniana è una soluzione altazimutale con base e supporti progettati per sostenere e muovere in altezza e azimut un telescopio, spesso un riflettore Newton.","strumentazione.html"],"doppia-ottica":["Una doppia ottica è una coppia di stelle apparentemente vicine sulla sfera celeste senza che la vicinanza osservata implichi un legame orbitale fra loro.","lezione-4-1.html"],"drizzle":["Drizzle è un metodo di ricostruzione e combinazione di immagini che utilizza campioni acquisiti in posizioni leggermente diverse sul sensore.","astrofotografia.html"],"dualismo-onda-corpuscolo":["L’espressione dualismo onda-corpuscolo richiama comportamenti della materia e della radiazione che non possono essere descritti interamente usando soltanto le immagini classiche di onda o particella.","lezione-4-3.html"],"duna":["Una duna è un accumulo di materiale granulare modellato dal trasporto del vento. Forma e movimento dipendono da sedimenti, disponibilità del materiale e regime dei venti.","lezione-3-2.html"],"ebollizione":["L’ebollizione è la vaporizzazione che avviene con formazione di bolle di vapore nel liquido, a condizioni determinate da temperatura e pressione.","lezione-3-2.html"],"eccentricita":["L’eccentricità descrive la forma di una conica. Nelle orbite ellittiche indica quanto la forma si discosta da una circonferenza, senza dipendere dalle dimensioni dell’orbita.","lezione-3-6.html"],"eccitazione-atomica":["L’eccitazione atomica è il passaggio di un atomo a uno stato energetico più elevato attraverso uno scambio di energia, senza necessariamente ionizzarlo.","lezione-4-3.html"],"eclissi":["Oscuramento totale o parziale di un astro dovuto all’interposizione di un altro corpo.","lezione-2-6.html"],"eclittica":["Cerchio della sfera celeste che descrive il percorso apparente annuo del Sole e corrisponde al piano dell’orbita terrestre.","lezione-2-2.html"],"eddington-arthur":["Arthur Stanley Eddington (1882–1944) fu un astronomo e fisico britannico che contribuì allo studio della struttura stellare e alla diffusione della relatività generale.","lezione-4-1.html"],"effemeridi":["Le effemeridi forniscono posizioni e altri dati astronomici in funzione del tempo, entro un riferimento, un modello e condizioni dichiarate.","lezione-9-3.html"],"effetto-cherenkov":["Emissione di luce da parte di una particella carica che attraversa un mezzo trasparente più velocemente della velocità di fase della luce in quel mezzo. Non viene superata la velocità della luce nel vuoto.","lezione-10-5.html"],"effetto-compton":["L’effetto Compton è la diffusione di un fotone da parte di un elettrone, con scambio di energia e quantità di moto.","lezione-10-3.html"],"effetto-doppler":["L’effetto Doppler collega il moto relativo fra sorgente e osservatore a una variazione della frequenza e della lunghezza d’onda ricevute.","lezione-4-3.html"],"effetto-fotoelettrico":["L’effetto fotoelettrico riguarda trasformazioni elettriche prodotte dall’assorbimento di radiazione; nel caso esterno comporta l’emissione di elettroni da un materiale.","astrofotografia.html"],"effetto-joule":["L’effetto Joule è la trasformazione di energia elettrica in energia interna associata al passaggio di corrente attraverso una resistenza.","strumentazione.html"],"effetto-serra":["L’effetto serra atmosferico deriva dall’interazione dell’atmosfera con la radiazione termica e modifica il bilancio energetico e la temperatura della superficie.","lezione-3-2.html"],"effetto-stark":["L’effetto Stark è la modifica dei livelli energetici e delle righe spettrali dovuta all’interazione con un campo elettrico.","lezione-4-3.html"],"effetto-tunnel":["L’effetto tunnel è un fenomeno quantistico che permette una probabilità di attraversamento di una barriera di potenziale anche quando l’energia non consentirebbe il passaggio nel modello classico.","lezione-4-1.html"],"effetto-zeeman":["L’effetto Zeeman è la modifica dei livelli energetici e delle righe spettrali di un sistema atomico in presenza di un campo magnetico.","lezione-2-3.html"],"efficienza-quantica":["L’efficienza quantica di un rivelatore descrive la frazione di fotoni incidenti che produce il segnale elettronico rilevato, secondo lunghezza d’onda e condizioni.","astrofotografia.html"],"einstein-albert":["Albert Einstein (1879–1955) sviluppò la relatività ristretta e generale e contribuì alla fisica quantistica della luce, con conseguenze centrali per l’astrofisica e la cosmologia.","lezione-6-5.html"],"elemento-chimico":["Un elemento chimico è identificato dal numero di protoni dei suoi nuclei; atomi con lo stesso numero atomico appartengono allo stesso elemento.","lezione-4-3.html"],"elettrone":["L’elettrone è una particella elementare della famiglia dei leptoni, con carica elettrica negativa, fondamentale nella struttura atomica e nei fenomeni elettromagnetici.","lezione-4-3.html"],"elettronegativita":["L’elettronegatività descrive la tendenza di un atomo coinvolto in un legame ad attrarre verso di sé la densità elettronica condivisa.","lezione-3-6.html"],"elettronvolt":["L’elettronvolt, simbolo eV, è un’unità di energia pari all’energia acquistata da una carica elementare attraversando una differenza di potenziale di un volt nel caso appropriato.","lezione-4-3.html"],"elio":["L’elio è l’elemento chimico con numero atomico due, indicato dal simbolo He. È uno dei principali costituenti cosmici.","lezione-4-1.html"],"eliocentrico":["Eliocentrico indica un riferimento con origine nel Sole. Nella storia dell’astronomia descrive anche modelli del sistema planetario centrati sul Sole.","lezione-3-1.html"],"eliopausa":["L’eliopausa è la regione di separazione fra il plasma dominato dal vento solare e il plasma del mezzo interstellare circostante.","lezione-2-3.html"],"eliosfera":["L’eliosfera è la regione dello spazio modellata dal vento solare e dal campo magnetico che esso trasporta, in interazione con il mezzo interstellare.","lezione-2-3.html"],"eliosismologia":["L’eliosismologia studia le oscillazioni del Sole per ricavare informazioni sulla sua struttura e sui movimenti interni.","lezione-2-3.html"],"elongazione":["Nell’uso osservativo l’elongazione descrive la separazione apparente dal Sole; occorre distinguere la separazione angolare totale dalla differenza di longitudine usata in alcune definizioni.","lezione-9-3.html"],"emissione-sincrotrone":["La radiazione di sincrotrone è prodotta da particelle cariche relativistiche la cui traiettoria viene curvata, tipicamente da un campo magnetico.","lezione-6-2.html"],"emissione-spontanea":["L’emissione spontanea è un processo nel quale un sistema eccitato passa a uno stato di energia inferiore emettendo radiazione senza che la transizione sia indotta da radiazione incidente.","lezione-4-3.html"],"emissione-stimolata":["L’emissione stimolata è una transizione radiativa indotta da radiazione incidente in un sistema eccitato, che può contribuire ad amplificare la radiazione.","lezione-4-3.html"],"emissione-termica":["L’emissione termica è radiazione legata allo stato termico della materia; lo spettro dipende anche da proprietà e condizioni del materiale, non sempre dalla sola temperatura.","lezione-4-3.html"],"encelado":["Encelado è un satellite ghiacciato di Saturno che emette pennacchi di gas e particelle dalla regione polare meridionale, collegati a un oceano interno.","lezione-3-4.html"],"encoder":["Un encoder è un dispositivo che traduce posizione o movimento in un segnale utilizzabile da un sistema di misura o controllo.","strumentazione.html"],"energia":["L’energia è una grandezza fisica che permette di descrivere e confrontare trasformazioni e trasferimenti; non è sinonimo di potenza o temperatura.","lezione-4-1.html"],"energia-attivazione":["L’energia di attivazione caratterizza la barriera energetica associata a un percorso di reazione e aiuta a comprendere perché una trasformazione possibile possa essere molto lenta.","lezione-5-4.html"],"energia-cinetica":["L’energia cinetica è l’energia associata al movimento rispetto a un sistema di riferimento; nel regime classico dipende dalla massa e dal quadrato della velocità.","lezione-3-6.html"],"energia-ionizzazione":["L’energia di ionizzazione è l’energia necessaria per rimuovere un elettrone da una specie isolata nello stato specificato. Il valore dipende dalla specie e dallo stato iniziale.","lezione-4-3.html"],"energia-legame-nucleare":["L’energia di legame nucleare è l’energia necessaria per separare completamente un nucleo nei suoi protoni e neutroni liberi.","lezione-10-4.html"],"energia-oscura":["Energia oscura è il nome dato alla componente o al meccanismo introdotto nei modelli cosmologici per descrivere l’espansione accelerata, la cui natura fisica resta oggetto di ricerca.","lezione-6-5.html"],"energia-potenziale":["L’energia potenziale descrive l’energia associata alla configurazione di un sistema soggetto a interazioni conservative, rispetto a un riferimento scelto.","lezione-3-6.html"],"entropia":["L’entropia è una grandezza di stato che descrive aspetti della distribuzione dell’energia e dei possibili stati microscopici; è fondamentale per comprendere la direzione dei processi termodinamici.","lezione-2-3.html"],"epoca-astronomica":["Un’epoca astronomica è una data di riferimento alla quale sono riferiti valori o parametri di un oggetto o di un modello.","lezione-1-6.html"],"equatore-celeste":["Cerchio massimo della sfera celeste ottenuto prolungando il piano dell’equatore terrestre.","lezione-1-6.html"],"equazione-stato":["Un’equazione di stato esprime una relazione fra grandezze che descrivono lo stato fisico della materia, come pressione, temperatura e densità.","lezione-4-1.html"],"equilibrio-chimico":["L’equilibrio chimico è una condizione nella quale, a condizioni fissate, le trasformazioni diretta e inversa si compensano e la composizione macroscopica non cambia nel tempo.","lezione-5-4.html"],"equilibrio-idrostatico":["L’equilibrio idrostatico descrive una configurazione in cui il gradiente di pressione bilancia la forza gravitazionale locale in un fluido.","lezione-4-1.html"],"equilibrio-termico":["Due sistemi sono in equilibrio termico quando hanno la stessa temperatura e, messi in contatto termico nelle condizioni considerate, non presentano uno scambio netto di calore.","lezione-7-6.html"],"equilibrio-termodinamico-locale":["L’equilibrio termodinamico locale è un’approssimazione nella quale piccole regioni di un sistema possono essere descritte con relazioni di equilibrio, anche se il sistema complessivo non è in equilibrio.","lezione-4-3.html"],"equinozio":["Un equinozio è l’istante in cui il Sole attraversa l’equatore celeste nel suo percorso apparente annuale; il termine indica anche il corrispondente punto d’intersezione con l’eclittica.","lezione-2-2.html"],"equinozio-riferimento":["L’equinozio di riferimento specifica l’orientamento di un sistema di coordinate equatoriali classico attraverso equatore ed equinozio adottati.","lezione-1-6.html"],"equivalenza-massa-energia":["L’equivalenza massa–energia collega la massa di un sistema alla sua energia a riposo attraverso E₀ = mc², dove c è la velocità della luce nel vuoto.","lezione-4-1.html"],"eratostene":["Eratostene di Cirene fu uno studioso greco del III secolo a.C., noto anche per aver stimato la circonferenza terrestre attraverso geometria, distanza e osservazioni solari.","lezione-1-2.html"],"eris":["Eris è un pianeta nano transnettuniano, con orbita molto eccentrica e inclinata, accompagnato dal satellite Disnomia.","lezione-3-5.html"],"erosione":["L’erosione è l’asportazione e il trasporto di materiale da una superficie per opera di agenti come acqua, vento, ghiaccio e gravità.","lezione-3-2.html"],"errore-casuale":["L’errore casuale è la componente dell’errore di misura che varia in modo imprevedibile fra ripetizioni effettuate in condizioni specificate.","lezione-9-4.html"],"errore-periodico":["L’errore periodico è una variazione ricorrente dell’inseguimento associata alla rotazione di componenti della trasmissione meccanica.","astrofotografia.html"],"errore-sistematico":["Un errore sistematico è una componente dell’errore di misura che nelle ripetizioni resta costante oppure varia in modo prevedibile.","lezione-9-4.html"],"esopianeta":["Un esopianeta è un pianeta esterno al Sistema solare, studiato attraverso osservazioni che ne vincolano orbita e proprietà fisiche.","lezione-10-1.html"],"esosfera":["L’esosfera è la regione più esterna di un’atmosfera, nella quale le collisioni fra particelle diventano molto rare.","lezione-3-2.html"],"esposizione":["L’esposizione è il processo con cui il rivelatore raccoglie radiazione durante una ripresa. Il tempo di posa è uno dei parametri che ne determinano il risultato.","astrofotografia.html"],"espulsione-massa-coronale":["Un’espulsione di massa coronale è una grande espulsione di plasma e campo magnetico dalla corona solare verso lo spazio interplanetario.","lezione-2-3.html"],"estere":["Un estere è un composto derivato formalmente da un acido sostituendo l’idrogeno di un gruppo ossidrilico acido con un gruppo organico.","lezione-10-2.html"],"estinzione-atmosferica":["L’estinzione atmosferica è l’attenuazione della radiazione diretta degli astri dovuta ad assorbimento e diffusione nell’atmosfera terrestre.","lezione-7-5.html"],"estinzione-interstellare":["L’estinzione interstellare è l’attenuazione della luce proveniente da una sorgente per effetto del materiale presente lungo il percorso fra le stelle.","lezione-4-3.html"],"etanolo":["L’etanolo, o alcol etilico, è il composto di formula CH₃CH₂OH. È un alcol e una delle molecole organiche studiate anche in astrochimica.","lezione-10-2.html"],"etere":["Gli eteri sono composti nei quali un ossigeno è collegato a due gruppi organici attraverso legami semplici.","lezione-10-2.html"],"euclid":["Euclid è una missione ESA, lanciata il 1º luglio 2023, che studia la distribuzione delle galassie e gli effetti della gravità per indagare materia oscura, energia oscura ed evoluzione cosmica.","lezione-6-4.html"],"europa-satellite":["Europa è un satellite galileiano di Giove con superficie ghiacciata e forti evidenze a favore di un oceano sotto il ghiaccio.","lezione-3-4.html"],"eutettico":["Un eutettico è una composizione di miscela associata a una temperatura minima di fusione o solidificazione nel sistema considerato a pressione specificata.","lezione-3-4.html"],"evaporazione":["L’evaporazione è il passaggio di molecole dalla superficie di un liquido alla fase gassosa; può avvenire anche sotto la temperatura di ebollizione.","lezione-7-6.html"],"evoluzione-stellare":["L’evoluzione stellare è l’insieme delle trasformazioni di struttura, composizione e proprietà osservabili che una stella attraversa nel tempo, secondo massa e condizioni iniziali e ambientali.","lezione-4-6.html"],"facola":["Una facola solare è una struttura luminosa associata all’attività magnetica, riconoscibile nella fotosfera e descritta secondo la banda osservata.","lezione-2-3.html"],"falsi-colori":["Una rappresentazione a falsi colori assegna colori visibili a misure o bande secondo una legenda, senza pretendere di riprodurre esattamente la percezione dell’occhio.","lezione-9-4.html"],"fase-lunare":["La fase lunare descrive la porzione dell’emisfero illuminato della Luna che vediamo dalla Terra, secondo la geometria Sole–Luna–osservatore.","lezione-2-4.html"],"fattore-scala":["Il fattore di scala descrive come cambiano nel tempo le distanze cosmologiche fra punti che seguono l’espansione media dell’Universo. È convenzionalmente normalizzato a uno oggi.","lezione-6-5.html"],"feedback-astrofisico":["Il feedback è l’insieme dei processi con cui stelle o nuclei attivi modificano l’ambiente che ne condiziona l’evoluzione, trasferendo energia, quantità di moto e materia.","lezione-6-2.html"],"feldspato":["I feldspati sono un gruppo di minerali silicatici a struttura tridimensionale, importanti componenti della crosta terrestre e di altri materiali planetari.","lezione-3-2.html"],"fermi-missione":["Fermi è un osservatorio spaziale della NASA, lanciato nel 2008, dedicato allo studio dei raggi gamma.","lezione-10-5.html"],"fermione":["Un fermione è una particella di spin semintero che segue la statistica di Fermi–Dirac; particelle identiche di questa famiglia rispettano il principio di esclusione.","lezione-4-6.html"],"ferro":["Il ferro è l’elemento chimico di numero atomico 26 e simbolo Fe, importante negli interni planetari, nei meteoriti e nell’interpretazione degli spettri.","lezione-4-6.html"],"ferromagnetismo":["Il ferromagnetismo è un comportamento collettivo della materia nel quale i momenti magnetici possono ordinarsi producendo magnetizzazione spontanea.","lezione-10-2.html"],"filamento-cosmico":["Un filamento cosmico è una struttura allungata della distribuzione di materia su grande scala, parte della rete cosmica.","lezione-6-4.html"],"filtro-banda-larga":["Un filtro a banda larga seleziona un intervallo relativamente ampio dello spettro, definito dalla propria curva di trasmissione.","astrofotografia.html"],"filtro-banda-stretta":["Un filtro a banda stretta seleziona un intervallo spettrale ridotto, spesso attorno a una riga di emissione astronomica.","astrofotografia.html"],"filtro-solare":["Un filtro solare per osservazione diretta è un dispositivo specificamente progettato per ridurre la radiazione a livelli appropriati nell’uso dichiarato e nella configurazione prevista.","lezione-2-3.html"],"fissione-nucleare":["La fissione nucleare è una trasformazione in cui un nucleo si divide in frammenti più leggeri; nei processi di interesse energetico il bilancio libera energia.","lezione-4-1.html"],"flash-elio":["Il flash dell’elio è la rapida accensione della fusione dell’elio in un nucleo stellare degenere, tipica di una fase evolutiva di stelle di piccola massa.","lezione-4-6.html"],"flat-field":["Un flat field è una ripresa di calibrazione di un campo uniformemente illuminato, usata per correggere variazioni relative di risposta e illuminazione nel sistema fotografico.","astrofotografia.html"],"fluoro":["Il fluoro è l’elemento chimico di simbolo F e numero atomico 9, appartenente agli alogeni; in astronomia può essere studiato anche attraverso molecole che lo contengono.","lezione-5-4.html"],"flusso-radiativo":["Nel linguaggio astronomico il flusso radiativo ricevuto indica comunemente la potenza che attraversa un’unità di area. Va distinto dal flusso radiante totale della terminologia radiometrica.","lezione-4-2.html"],"flyby":["Un flyby è un incontro ravvicinato nel quale una sonda passa accanto a un corpo celeste e prosegue la traiettoria senza entrare in orbita attorno a esso.","lezione-10-5.html"],"focale":["La lunghezza focale è una proprietà del sistema ottico che determina la scala dell’immagine e, con oculare o sensore, il modo in cui la osserviamo.","lezione-7-4.html"],"focheggiatore":["Il focheggiatore è il dispositivo che permette di portare oculare o sensore nella posizione in cui il sistema ottico forma un’immagine nitida.","strumentazione.html"],"fondo-cielo":["Il fondo cielo è il contributo diffuso registrato attorno alle sorgenti di interesse, prodotto da componenti naturali e artificiali e distinto dai contributi propri dello strumento.","lezione-7-5.html"],"formaldeide":["La formaldeide, o metanale, è una molecola di formula H₂CO: contiene carbonio, idrogeno e ossigeno ed è la più semplice aldeide.","lezione-10-2.html"],"formammide":["La formammide, detta anche formamide, è una molecola organica di formula NH₂CHO, contenente una funzione ammidica e studiata anche nella chimica prebiotica.","lezione-10-2.html"],"formula-chimica":["Una formula chimica rappresenta la composizione di una specie attraverso simboli degli elementi, indici numerici ed eventuali indicazioni di carica o struttura.","lezione-3-6.html"],"formula-minima":["La formula minima, o empirica, esprime il rapporto intero più semplice tra gli atomi degli elementi di un composto, senza necessariamente indicare una singola molecola.","lezione-10-2.html"],"formula-molecolare":["La formula molecolare indica quali elementi e quanti atomi di ciascun elemento compongono una singola molecola.","lezione-10-2.html"],"forza":["Una forza descrive un’interazione capace di modificare il moto o deformare un corpo; in meccanica classica è una grandezza vettoriale misurata in newton.","lezione-3-6.html"],"forza-centripeta":["Forza centripeta indica il ruolo della componente della forza risultante diretta verso il centro nel mantenere un moto circolare, non una nuova interazione da aggiungere alle altre.","lezione-3-6.html"],"forze-van-der-waals":["Le forze di van der Waals comprendono interazioni fra atomi o molecole associate a distribuzioni elettriche permanenti, indotte o fluttuanti, importanti per molte proprietà della materia.","lezione-5-4.html"],"fosforo":["Il fosforo è l’elemento chimico di numero atomico 15 e simbolo P, importante nelle molecole della vita terrestre e nella ricerca astrochimica.","lezione-10-2.html"],"fotodiodo":["Un fotodiodo è un rivelatore che converte radiazione assorbita in una risposta elettrica; nei dispositivi a semiconduttore intervengono portatori di carica generati dalla luce.","astrofotografia.html"],"fotodissociazione":["La fotodissociazione è la separazione di una molecola in frammenti in seguito all’assorbimento di radiazione. È un processo importante nella chimica dei gas irradiati.","lezione-5-4.html"],"fotoionizzazione":["La fotoionizzazione è la rimozione di un elettrone da un atomo o da una molecola attraverso l’assorbimento di radiazione sufficientemente energetica.","lezione-5-4.html"],"fotometria":["La fotometria astronomica misura la radiazione ricevuta dalle sorgenti in bande e condizioni definite, per confrontarne flusso e variazioni.","lezione-4-2.html"],"fotometria-differenziale":["La fotometria differenziale misura la luminosità di una sorgente rispetto a una o più sorgenti di confronto, con controlli su stabilità e condizioni osservative.","lezione-4-2.html"],"fotometro":["Un fotometro misura la radiazione ricevuta da una sorgente in una determinata banda. In astronomia permette di quantificare la brillanza apparente e seguirne le variazioni nel tempo, per esempio durante un transito o un’occultazione.","lezione-4-2.html"],"fotomoltiplicatore":["Un fotomoltiplicatore è un rivelatore che converte luce in elettroni e amplifica il segnale attraverso una catena di emissioni secondarie.","lezione-9-4.html"],"fotone":["Il fotone è il quanto della radiazione elettromagnetica: l’energia di un singolo fotone è legata alla frequenza della radiazione.","lezione-4-3.html"],"fotosfera":["La fotosfera è lo strato da cui proviene gran parte della luce continua visibile di una stella. Nel Sole costituisce la superficie apparente osservata in luce bianca.","lezione-2-3.html"],"fowler-william":["William Alfred Fowler (1911–1995) fu un fisico statunitense, Nobel per la fisica nel 1983 per studi teorici e sperimentali sulle reazioni nucleari che formano elementi nell’Universo.","lezione-10-4.html"],"frazionamento-isotopico":["Il frazionamento isotopico è la variazione dei rapporti fra isotopi prodotta da processi fisici o chimici che li distribuiscono in modo differente.","lezione-10-2.html"],"frequenza":["La frequenza indica quanti cicli di un fenomeno periodico si ripetono nell’unità di tempo; si misura in hertz, cioè cicli al secondo.","lezione-4-3.html"],"full-well":["La full well capacity è la quantità di carica che un elemento del sensore può accumulare utilmente prima della saturazione secondo le condizioni dichiarate.","astrofotografia.html"],"funzione-diffusione-punto":["La PSF descrive come un sistema di osservazione distribuisce nell’immagine il segnale proveniente da una sorgente puntiforme.","astrofotografia.html"],"funzione-onda":["La funzione d’onda è una descrizione matematica dello stato quantistico che permette, attraverso regole appropriate, di calcolare probabilità dei risultati delle misure.","lezione-4-3.html"],"fuoco":["Il fuoco e il piano focale descrivono dove un sistema ottico forma l’immagine di sorgenti lontane.","lezione-7-3.html"],"fuoco-diretto":["Nella fotografia al fuoco diretto il sensore registra l’immagine formata dal telescopio senza un oculare usato per proiettarla.","astrofotografia.html"],"fusione-nucleare":["La fusione nucleare combina nuclei leggeri in prodotti più pesanti. Nelle stelle alcune catene di reazioni liberano l’energia che ne sostiene l’emissione.","lezione-4-1.html"],"fusione-stato":["La fusione come cambiamento di stato è il passaggio dalla fase solida alla fase liquida; non va confusa con la fusione nucleare.","lezione-3-2.html"],"fwhm":["La FWHM è la larghezza completa di un profilo misurata al livello di metà del suo massimo rispetto al fondo, secondo il modello e la procedura adottati.","lezione-7-5.html"],"gaia":["Gaia è la missione astrometrica ESA lanciata il 19 dicembre 2013, dedicata a misure di posizioni, moti e altre proprietà di moltissime sorgenti celesti.","lezione-9-4.html"],"galassia":["Grande sistema gravitazionale di stelle, generalmente accompagnate da gas e polveri.","lezione-6-1.html"],"galassia-ellittica":["Una galassia ellittica ha una distribuzione della luce generalmente regolare, con contorni proiettati ellittici e senza evidenti bracci a spirale.","lezione-6-2.html"],"galassia-irregolare":["Una galassia irregolare non presenta una struttura ordinata riconducibile chiaramente alle principali famiglie ellittiche o spirali.","lezione-6-2.html"],"galassia-lenticolare":["Una galassia lenticolare possiede un disco e una componente centrale prominente, ma non mostra bracci a spirale marcati nella classificazione ordinaria.","lezione-6-2.html"],"galassia-nana":["Una galassia nana è un sistema galattico di dimensioni, luminosità o massa relativamente contenute rispetto alle grandi galassie, secondo il criterio adottato.","lezione-6-2.html"],"galassia-seyfert":["Una galassia di Seyfert ospita un nucleo attivo brillante con caratteristiche righe di emissione nello spettro; la galassia ospite è generalmente distinguibile.","lezione-6-2.html"],"galassia-spirale":["Una galassia spirale possiede un disco con strutture a bracci, insieme a componenti che possono comprendere rigonfiamento centrale e alone.","lezione-6-2.html"],"galassia-spirale-barrata":["Una spirale barrata mostra una struttura stellare allungata nella regione centrale, dalla quale o nelle cui vicinanze si sviluppano i bracci.","lezione-6-2.html"],"galassie-interagenti":["Le galassie interagenti sono sistemi che modificano reciprocamente struttura e dinamica attraverso la gravità e, quando presente, l’interazione del gas.","lezione-6-2.html"],"galilei-galileo":["Galileo Galilei (1564–1642) contribuì alla nuova fisica del moto e utilizzò il cannocchiale per osservazioni che trasformarono il dibattito astronomico del Seicento.","lezione-3-4.html"],"galileo-sonda":["Galileo fu una missione NASA dedicata al sistema di Giove, comprendente un veicolo orbitale e una sonda che entrò nell’atmosfera del pianeta nel 1995.","lezione-3-3.html"],"gamow-george":["George Gamow (1904–1968) fu un fisico teorico e divulgatore che contribuì alla fisica nucleare e allo sviluppo delle idee sull’Universo caldo primordiale.","lezione-6-5.html"],"ganimede":["Ganimede è il maggiore satellite del Sistema solare e una delle quattro lune galileiane di Giove; possiede un campo magnetico proprio.","lezione-3-4.html"],"gas-ideale":["Il gas ideale è un modello nel quale le particelle sono trattate con volume proprio trascurabile e interazioni semplificate; collega pressione, volume, temperatura e quantità di sostanza.","lezione-4-1.html"],"gas-interstellare":["Il gas interstellare è la componente gassosa del materiale fra le stelle, presente in fasi molecolari, atomiche e ionizzate con condizioni diverse.","lezione-5-4.html"],"gas-intraammasso":["Il gas intraammasso è la componente gassosa diffusa fra le galassie di un ammasso, spesso molto calda e osservabile nei raggi X.","lezione-6-4.html"],"gas-nobile":["I gas nobili sono gli elementi del gruppo 18 della tavola periodica, caratterizzati da configurazioni elettroniche esterne particolarmente stabili nelle condizioni ordinarie.","lezione-10-2.html"],"ghiaccio-amorfo":["Il ghiaccio amorfo è acqua solida senza l’ordine cristallino a lungo raggio del ghiaccio ordinario.","lezione-3-5.html"],"gigante-rossa":["Una gigante rossa è una stella evoluta con strati esterni molto espansi e temperatura superficiale relativamente bassa. La grande superficie può renderla molto luminosa.","lezione-4-6.html"],"giorno-siderale":["Il giorno siderale medio dura circa 23 ore, 56 minuti e 4 secondi di tempo solare medio: usa un riferimento celeste diverso dal Sole.","lezione-2-1.html"],"giorno-solare":["Il giorno solare è l’intervallo fra due successivi passaggi del Sole sullo stesso meridiano; si distinguono il giorno solare vero e il riferimento medio.","lezione-2-1.html"],"giotto":["Giotto fu una missione dell’ESA che incontrò la cometa di Halley nel 1986 e la cometa Grigg–Skjellerup nel 1992.","lezione-3-5.html"],"giotto-sonda":["Sonda ESA che nel 1986 sorvolò la cometa di Halley e ne riprese il nucleo.","lezione-3-5.html"],"giove":["Giove è il pianeta più grande del Sistema solare, un gigante composto soprattutto da idrogeno ed elio, con atmosfera dinamica e un esteso sistema di satelliti.","lezione-3-3.html"],"glicina":["La glicina è il più semplice amminoacido delle proteine, con formula C₂H₅NO₂. È importante anche nello studio della chimica dei materiali extraterrestri.","lezione-10-2.html"],"globulo-bok":["Un globulo di Bok è una piccola nube densa di gas e polveri, spesso osservata come struttura scura contro un fondo luminoso e collegata allo studio della formazione stellare.","lezione-4-5.html"],"gluone":["Il gluone è il bosone associato all’interazione forte nella cromodinamica quantistica. Partecipa alla dinamica che lega quark e antiquark nei sistemi adronici.","lezione-6-5.html"],"gnomone":["Lo gnomone è uno stilo che proietta un’ombra usata per studiare la posizione del Sole o indicare il tempo su un quadrante opportunamente costruito.","guide.html"],"goto":["GoTo indica la funzione con cui una montatura motorizzata porta automaticamente lo strumento verso un bersaglio selezionato, usando un modello di puntamento.","strumentazione.html"],"grado-angolare":["Il grado sessagesimale è un’unità di angolo: un giro completo ne contiene 360 e un angolo retto 90.","lezione-1-1.html"],"grandezza-scalare":["Una grandezza scalare viene descritta, nel contesto fisico considerato, da un valore numerico e un’unità, senza attribuirle direzione e verso come a un vettore.","lezione-3-6.html"],"granito":["Il granito è una roccia magmatica intrusiva, ricca di quarzo e feldspati, formata dalla solidificazione di un fuso in profondità.","lezione-3-2.html"],"granulazione-solare":["La granulazione solare è la trama variabile della fotosfera associata ai moti convettivi del plasma, con regioni relativamente luminose e zone intergranulari più scure.","lezione-2-3.html"],"gravitazione":["La gravitazione governa l’interazione fra masse nella descrizione newtoniana; in relatività generale viene descritta attraverso la geometria dello spaziotempo.","lezione-3-6.html"],"gruppo-funzionale":["Un gruppo funzionale è un insieme riconoscibile di atomi o legami che contribuisce al comportamento chimico di una molecola.","lezione-10-2.html"],"gruppo-locale":["Il Gruppo Locale è l’insieme di galassie gravitazionalmente associate che comprende la Via Lattea, Andromeda, la galassia del Triangolo e numerosi sistemi più piccoli.","lezione-6-4.html"],"gruppo-periodico":["Un gruppo è una colonna della tavola periodica; nella numerazione moderna le colonne principali sono identificate da numeri da 1 a 18.","lezione-4-3.html"],"guadagno-elettronico":["Nella ripresa digitale il guadagno descrive l’amplificazione e la conversione del segnale del sensore; non aumenta il numero di fotoni raccolti.","astrofotografia.html"],"guida-fuori-asse":["La guida fuori asse preleva una piccola parte del fascio del telescopio principale per una camera di guida, senza utilizzare un telescopio guida separato.","astrofotografia.html"],"h-alfa":["H-alfa è una riga spettrale dell’idrogeno visibile nel rosso, attorno a 656,3 nanometri, prodotta dalla transizione elettronica dal livello 3 al livello 2.","lezione-4-3.html"],"h-beta":["H-beta è una riga spettrale dell’idrogeno della serie di Balmer, vicina a 486,1 nanometri nel visibile. In emissione corrisponde alla transizione dal livello principale quattro al due.","lezione-4-3.html"],"hack-margherita":["Margherita Hack (1922–2013) fu un’astrofisica italiana attiva nella spettroscopia e nell’evoluzione stellare, nella direzione della ricerca e nella divulgazione al pubblico.","lezione-4-3.html"],"halley-edmond":["Edmond Halley (1656–1742), chiamato anche Edmund, fu un astronomo inglese noto per lo studio delle orbite cometarie e la previsione del ritorno della cometa che porta il suo nome.","lezione-3-5.html"],"hayabusa2":["Hayabusa2 è la missione giapponese JAXA che studiò l’asteroide Ryugu e riportò sulla Terra campioni del suo materiale nel 2020.","lezione-10-5.html"],"herschel-caroline":["Caroline Lucretia Herschel (1750–1848) fu un’astronoma che scoprì comete e svolse un importante lavoro di osservazione, calcolo e revisione di cataloghi.","lezione-9-4.html"],"herschel-missione":["Herschel fu un osservatorio dell’ESA dedicato al lontano infrarosso e al submillimetrico, lanciato nel 2009; le osservazioni terminarono nel 2013.","lezione-4-5.html"],"herschel-william":["William Herschel (1738–1822) fu un astronomo e costruttore di telescopi, scopritore di Urano nel 1781 e protagonista dello studio sistematico del cielo profondo.","lezione-5-1.html"],"hertz":["L’hertz, simbolo Hz, è l’unità SI della frequenza e corrisponde a un ciclo al secondo.","lezione-4-3.html"],"herzberg-gerhard":["Gerhard Herzberg (1904–1999) fu un fisico e spettroscopista, premiato con il Nobel per la chimica nel 1971 per studi sulla struttura delle molecole e dei radicali.","lezione-4-3.html"],"hi":["HI indica idrogeno atomico neutro: il nucleo mantiene il proprio elettrone. La sigla distingue questo stato dall’idrogeno ionizzato e dall’idrogeno molecolare.","lezione-5-4.html"],"hii":["Una regione HII è una zona di gas nella quale l’idrogeno è in larga parte ionizzato. È spesso associata alla radiazione di stelle giovani molto calde.","lezione-5-4.html"],"hill-sfera":["La sfera di Hill è una stima della regione di influenza orbitale di un corpo rispetto alla perturbazione di un corpo più massiccio attorno al quale orbita.","lezione-3-4.html"],"hipparcos":["Hipparcos fu la missione astrometrica ESA che osservò fra il 1989 e il 1993, producendo cataloghi fondamentali di posizioni, parallassi e moti stellari.","lezione-9-4.html"],"hohmann-trasferimento":["Il trasferimento di Hohmann collega idealmente due orbite circolari complanari attraverso un arco ellittico tangente a entrambe, con variazioni di velocità appropriate.","lezione-10-5.html"],"hoyle-fred":["Fred Hoyle (1915–2001) fu un astrofisico britannico importante per la nucleosintesi stellare e per la storia dei modelli cosmologici.","lezione-4-6.html"],"hubble-edwin":["Edwin Powell Hubble (1889–1953) fu un astronomo statunitense il cui lavoro sulle distanze extragalattiche e sulle galassie contribuì alla costruzione della cosmologia osservativa.","lezione-6-3.html"],"hubble-lemaitre-legge":["La legge di Hubble–Lemaître collega l’espansione cosmica alle distanze: nel regime osservativo vicino, la velocità di recessione è approssimativamente proporzionale alla distanza.","lezione-6-5.html"],"hubble-telescopio":["Hubble è un osservatorio spaziale NASA/ESA lanciato nel 1990, con specchio principale di 2,4 metri. Osserva soprattutto in ultravioletto, visibile e vicino infrarosso.","lezione-10-5.html"],"huygens-christiaan":["Christiaan Huygens (1629–1695) fu un fisico, matematico e astronomo olandese, importante per ottica, meccanica, misura del tempo e osservazioni di Saturno.","lezione-3-4.html"],"huygens-sonda":["Huygens fu la sonda ESA trasportata da Cassini che il 14 gennaio 2005 attraversò l’atmosfera di Titano e raggiunse la superficie, raccogliendo immagini e misure.","lezione-10-5.html"],"icrs":["L’International Celestial Reference System è un sistema di riferimento celeste moderno, realizzato attraverso posizioni di sorgenti extragalattiche e collegamenti con cataloghi osservativi.","lezione-1-6.html"],"idratazione":["Idratazione indica processi di associazione, incorporazione o reazione con acqua; il significato preciso dipende dal contesto chimico o mineralogico.","lezione-3-2.html"],"idrocarburi-policiclici-aromatici":["Gli idrocarburi policiclici aromatici, indicati con IPA o PAH, sono una famiglia di molecole del carbonio con più anelli aromatici; le loro firme sono importanti nell’astronomia infrarossa.","lezione-5-4.html"],"idrocarburo":["Un idrocarburo è un composto costituito soltanto da carbonio e idrogeno.","lezione-10-2.html"],"idrogeno":["L’idrogeno, simbolo H, è l’elemento con numero atomico uno ed è il più abbondante nell’Universo.","lezione-4-1.html"],"idrogeno-molecolare":["L’idrogeno molecolare H₂ è formato da due atomi di idrogeno legati; costituisce una componente fondamentale delle nubi molecolari.","lezione-4-5.html"],"idrolisi":["L’idrolisi è una trasformazione chimica nella quale l’acqua partecipa alla reazione, spesso contribuendo alla scissione di un composto o alla modifica degli equilibri delle specie disciolte.","lezione-10-2.html"],"impulso-forza":["L’impulso di una forza descrive la sua azione accumulata nel tempo ed è collegato alla variazione della quantità di moto. È una grandezza vettoriale.","lezione-10-5.html"],"incertezza-misura":["L’incertezza di misura esprime la dispersione dei valori attribuibili alla grandezza misurata, tenendo conto delle informazioni disponibili e del procedimento utilizzato.","lezione-9-4.html"],"inclinazione-assiale":["L’inclinazione assiale è l’angolo fra l’asse di rotazione di un corpo e la normale al piano orbitale scelto.","lezione-2-2.html"],"inclinazione-orbitale":["L’inclinazione orbitale è l’angolo che descrive l’orientamento del piano di un’orbita rispetto a un piano di riferimento dichiarato.","lezione-3-6.html"],"indice-di-colore":["L’indice di colore è la differenza fra le magnitudini di un oggetto misurate in due bande fotometriche definite. Descrive il rapporto fra la luce ricevuta nelle due bande.","lezione-4-3.html"],"indice-di-rifrazione":["L’indice di rifrazione collega la velocità di fase della luce nel vuoto a quella nel mezzo e contribuisce a descrivere come la luce si propaga e si devia.","lezione-7-3.html"],"induzione-elettromagnetica":["L’induzione elettromagnetica è il fenomeno per cui una variazione del flusso magnetico concatenato a un circuito produce una forza elettromotrice.","lezione-8-3.html"],"inerzia":["L’inerzia è la proprietà per cui un corpo mantiene il proprio stato di moto in assenza di una risultante esterna; la massa misura la risposta all’accelerazione nel regime classico.","lezione-3-6.html"],"inflazione-cosmica":["L’inflazione cosmica è una fase ipotizzata di espansione accelerata nell’Universo molto primordiale, proposta per spiegare proprietà su grande scala e l’origine delle perturbazioni cosmiche.","lezione-6-5.html"],"infrarosso":["L’infrarosso è una regione dello spettro elettromagnetico a lunghezze d’onda maggiori del rosso visibile, studiata con rivelatori adatti.","lezione-10-5.html"],"ingrandimento":["L’ingrandimento angolare indica quanto aumenta l’angolo sotto cui osserviamo un soggetto attraverso lo strumento.","lezione-7-4.html"],"inquinamento-luminoso":["L’inquinamento luminoso è l’alterazione dell’ambiente notturno dovuta alla luce artificiale, comprendendo chiarore del cielo, abbagliamento e luce intrusiva.","lezione-7-6.html"],"insight":["InSight fu un lander NASA operativo su Marte dal 2018 al 2022, dedicato allo studio dell’interno del pianeta attraverso misure geofisiche.","lezione-3-2.html"],"interazione-debole":["L’interazione debole è un’interazione fondamentale coinvolta in trasformazioni di particelle, decadimenti beta e processi essenziali per la produzione di energia nelle stelle.","lezione-2-3.html"],"interazione-forte":["L’interazione forte è una delle interazioni fondamentali. Agisce fra quark e gluoni; la sua manifestazione residua fra nucleoni contribuisce al legame dei nuclei atomici.","lezione-4-6.html"],"interferenza":["L’interferenza è il risultato della sovrapposizione di onde, che può produrre rafforzamenti o attenuazioni secondo le loro relazioni di fase.","lezione-7-5.html"],"interferometria":["L’interferometria ricava informazioni confrontando segnali attraverso le loro relazioni ondulatorie. In astronomia permette anche di combinare osservazioni da telescopi separati.","lezione-7-3.html"],"interferometro":["Un interferometro è uno strumento o un sistema che combina segnali ondulatori per misurarne le differenze attraverso l’interferenza. In astronomia può collegare telescopi separati: la tecnica impiegata si chiama interferometria.","lezione-7-3.html"],"intervallo-dinamico":["L’intervallo dinamico esprime il rapporto fra il segnale più grande utilizzabile e il livello minimo distinguibile secondo una definizione di misura dichiarata.","astrofotografia.html"],"invarianza-di-lorentz":["Simmetria della descrizione relativistica secondo cui le leggi fisiche mantengono la propria forma nel passaggio tra sistemi inerziali collegati da trasformazioni di Lorentz. Le singole misure di spazio e tempo possono invece cambiare.","lezione-10-3.html"],"io-satellite":["Io è uno dei quattro satelliti galileiani di Giove e presenta un’intensa attività vulcanica alimentata soprattutto dal riscaldamento mareale.","lezione-3-4.html"],"ione":["Uno ione è una specie atomica o molecolare con carica elettrica netta, dovuta a uno squilibrio fra cariche positive e negative.","lezione-5-4.html"],"ione-triidrogeno":["Lo ione triidrogeno, H₃⁺, è una specie molecolare positiva formata da tre nuclei di idrogeno e due elettroni; è importante nella chimica e nell’emissione infrarossa di alcuni gas astronomici.","lezione-3-3.html"],"ionizzazione":["La ionizzazione trasforma un atomo o una molecola neutri in una particella carica, attraverso perdita o acquisto di elettroni. In astrofisica ricorre spesso il distacco di elettroni dovuto a radiazione o urti.","lezione-4-3.html"],"ionizzazione-collisionale":["L’ionizzazione collisionale avviene quando una collisione trasferisce a un atomo o a una molecola energia sufficiente per liberare uno o più elettroni.","lezione-8-3.html"],"ionosfera":["La ionosfera è la regione dell’atmosfera nella quale ioni ed elettroni liberi influenzano significativamente le proprietà del mezzo, compresa la propagazione delle onde radio.","lezione-8-3.html"],"ipparco-nicea":["Ipparco di Nicea fu un astronomo e matematico greco del II secolo a.C., legato allo studio delle posizioni stellari, dei moti celesti e della precessione degli equinozi.","lezione-1-6.html"],"irradianza-solare":["L’irradianza solare è la potenza radiativa del Sole ricevuta per unità di area, con distanza, orientamento e intervallo spettrale specificati.","lezione-2-3.html"],"isobaro-nucleare":["Due nuclidi sono isobari quando hanno lo stesso numero di massa A ma diverso numero atomico Z.","lezione-10-4.html"],"isomeria":["L’isomeria è la possibilità che sostanze con la stessa formula molecolare abbiano una diversa organizzazione degli atomi e proprietà differenti.","lezione-5-4.html"],"isomero-nucleare":["Un isomero nucleare è uno stato eccitato relativamente longevo di un nucleo, distinto da uno stato di energia più bassa dello stesso nuclide.","lezione-10-4.html"],"isotono":["Due nuclidi sono isotoni quando hanno lo stesso numero di neutroni ma diverso numero di protoni.","lezione-10-4.html"],"isotopo":["Gli isotopi di uno stesso elemento hanno uguale numero di protoni ma diverso numero di neutroni nel nucleo.","lezione-4-3.html"],"isotopologo":["Un isotopologo è una specie molecolare che differisce da un’altra per la composizione isotopica degli atomi, conservando il tipo di struttura chimica considerato.","lezione-5-4.html"],"isotropia":["L’isotropia è l’indipendenza di una proprietà dalla direzione considerata; bisogna specificare quale proprietà e quale modello si stanno descrivendo.","lezione-4-2.html"],"istogramma":["Un istogramma rappresenta la distribuzione di valori in intervalli; in una fotografia astronomica può mostrare quanti pixel appartengono a ciascun intervallo di luminosità.","astrofotografia.html"],"iupac":["IUPAC è l’Unione internazionale di chimica pura e applicata, che elabora raccomandazioni per nomenclatura, terminologia, simboli e dati di riferimento della chimica.","lezione-4-3.html"],"j2000":["J2000.0 è l’epoca convenzionale corrispondente al 1° gennaio 2000 alle 12 nella scala TT, usata anche per specificare riferimenti astronomici classici.","lezione-1-6.html"],"james-webb":["James Webb è un osservatorio spaziale NASA/ESA/CSA, lanciato il 25 dicembre 2021 e progettato soprattutto per l’astronomia infrarossa.","lezione-10-5.html"],"jansky":["Il jansky, simbolo Jy, è un’unità di densità di flusso spettrale usata soprattutto in radioastronomia. Vale 10⁻²⁶ watt per metro quadrato per hertz.","lezione-10-5.html"],"jeans-instabilita":["L’instabilità di Jeans descrive, in un modello semplificato, le condizioni in cui una perturbazione di densità può crescere perché la gravità prevale sulla risposta della pressione.","lezione-4-5.html"],"jet-astrofisico":["Un jet astrofisico è un flusso di materia relativamente collimato, osservato in contesti come oggetti stellari giovani, sistemi compatti e nuclei galattici attivi.","lezione-6-2.html"],"joule":["Il joule, simbolo J, è l’unità SI dell’energia e del lavoro. Permette di confrontare trasferimenti energetici di natura diversa usando la stessa unità.","lezione-4-1.html"],"juice":["JUICE è la missione ESA Jupiter Icy Moons Explorer, dedicata allo studio di Giove, del suo ambiente e delle lune ghiacciate Ganimede, Callisto ed Europa.","lezione-3-3.html"],"juno":["Juno è una missione NASA lanciata nel 2011 e arrivata in orbita attorno a Giove nel luglio 2016, progettata per studiarne atmosfera, interno, campi e ambiente polare.","lezione-3-3.html"],"kelvin":["Il kelvin, simbolo K, è l’unità del Sistema Internazionale per la temperatura termodinamica.","lezione-4-3.html"],"kelvin-helmholtz-contrazione":["La contrazione di Kelvin–Helmholtz descrive una fase in cui un oggetto autogravitante perde energia radiando e si contrae, liberando energia gravitazionale.","lezione-4-5.html"],"kepler-missione":["Kepler fu un osservatorio NASA lanciato nel marzo 2009 per cercare esopianeti mediante misure ripetute della luminosità stellare; proseguì anche con il programma K2.","lezione-10-1.html"],"keplero-giovanni":["Giovanni Keplero, o Johannes Kepler (1571–1630), formulò tre leggi del moto planetario e contribuì allo sviluppo dell’ottica e dell’astronomia matematica.","lezione-3-6.html"],"keplero-leggi":["Le tre leggi di Keplero descrivono forma delle orbite, variazione del moto e relazione fra periodo e dimensione orbitale nel modello kepleriano.","lezione-3-6.html"],"kerr-buco-nero":["Il modello di Kerr descrive nella relatività generale un buco nero rotante e senza carica elettrica, caratterizzato da massa e momento angolare.","lezione-10-3.html"],"kilonova":["Una kilonova è un fenomeno luminoso transitorio associato a materiale espulso in alcune fusioni di oggetti compatti, riscaldato dal decadimento di nuclei radioattivi appena prodotti.","lezione-10-4.html"],"kiloparsec":["Il kiloparsec, simbolo kpc, è una distanza pari a mille parsec, cioè circa 3.262 anni luce.","lezione-6-3.html"],"kirchhoff-radiazione":["La legge di Kirchhoff collega emissione termica e assorbimento: all’equilibrio termodinamico, per le stesse condizioni spettrali e geometriche, emissività e assorbività coincidono.","lezione-4-3.html"],"kirkwood-lacune":["Le lacune di Kirkwood sono diminuzioni nella distribuzione dei semiassi maggiori degli asteroidi della fascia principale, associate a risonanze orbitali con Giove.","lezione-3-5.html"],"kuiper-fascia":["La fascia di Kuiper è una vasta popolazione di corpi esterni del Sistema solare, situata oltre l’orbita di Nettuno e composta in gran parte da materiali rocciosi e ghiacci.","lezione-3-5.html"],"lagrange-punti":["Nel problema ristretto circolare dei tre corpi, i punti di Lagrange sono cinque posizioni di equilibrio nel riferimento che ruota con i due corpi principali.","lezione-10-5.html"],"lampo-gamma":["Un lampo gamma è un evento transitorio con intensa emissione di raggi gamma, studiato attraverso durata, spettro ed emissione successiva.","lezione-10-4.html"],"lampo-radio-veloce":["Un lampo radio veloce è un impulso radio astronomico molto breve, spesso proveniente da grandi distanze cosmiche.","lezione-10-3.html"],"lander":["Un lander è un veicolo spaziale progettato per raggiungere e operare sulla superficie di un corpo celeste; può trasportare strumenti fissi e, in alcune missioni, un veicolo mobile.","lezione-10-5.html"],"lantanoide":["I lantanoidi sono la serie di elementi dal lantanio al lutezio, con numeri atomici da 57 a 71 e proprietà chimiche affini.","lezione-10-4.html"],"larghezza-equivalente":["La larghezza equivalente riassume l’area di una riga rispetto al continuo, esprimendola come la larghezza di un rettangolo equivalente con altezza fissata dal riferimento.","lezione-4-3.html"],"latitudine":["La latitudine geografica indica quanto un luogo si trova a nord o a sud dell’equatore; nel modello terrestre sferico è un angolo compreso fra −90° e +90°.","lezione-1-2.html"],"lavoisier-antoine":["Antoine-Laurent Lavoisier (1743–1794) fu un chimico francese fondamentale per la chimica quantitativa e per la comprensione della combustione.","lezione-10-2.html"],"lavoro-meccanico":["Il lavoro meccanico misura il trasferimento di energia associato a una forza lungo uno spostamento; conta la componente della forza nella direzione dello spostamento.","lezione-3-6.html"],"leavitt-henrietta":["Henrietta Swan Leavitt (1868–1921) fu l’astronoma che individuò una relazione fra periodo e luminosità delle Cefeidi, fondamentale per la misura delle distanze cosmiche.","lezione-6-3.html"],"legame-chimico":["Un legame chimico è un’interazione che mantiene una struttura di atomi in una configurazione legata, coinvolgendo nuclei ed elettroni.","lezione-5-4.html"],"legame-covalente":["Il legame covalente unisce atomi attraverso una distribuzione elettronica condivisa; nella descrizione introduttiva viene rappresentato mediante una o più coppie di elettroni di legame.","lezione-5-4.html"],"legame-idrogeno":["Il legame a idrogeno è un’interazione nella quale un idrogeno già legato a un atomo partecipa a un’ulteriore associazione con un altro atomo o gruppo appropriato.","lezione-5-4.html"],"legame-ionico":["Il legame ionico è la coesione associata all’interazione elettrostatica fra ioni di carica opposta, particolarmente importante nella descrizione di molti sali solidi.","lezione-5-4.html"],"legame-metallico":["Il legame metallico descrive la coesione di un metallo attraverso elettroni delocalizzati su molti centri atomici, anziché attribuiti esclusivamente a coppie di atomi.","lezione-5-4.html"],"legame-polare":["Un legame covalente polare presenta una distribuzione elettronica asimmetrica che produce cariche parziali sui partner del legame.","lezione-10-2.html"],"legge-boyle":["La legge di Boyle descrive l’inversa proporzionalità fra pressione e volume di una quantità fissata di gas ideale a temperatura costante.","lezione-3-3.html"],"legge-inverso-quadrato":["La legge dell’inverso del quadrato descrive una grandezza che diminuisce in proporzione al quadrato della distanza nelle condizioni fisiche cui la relazione si applica.","lezione-4-2.html"],"legge-ohm":["La legge di Ohm lega tensione, corrente e resistenza nei componenti che si comportano in modo ohmico, a condizioni fisiche fissate.","strumentazione.html"],"legge-stefan-boltzmann":["La legge di Stefan–Boltzmann lega la potenza termica totale emessa da un corpo nero per unità di superficie alla quarta potenza della temperatura assoluta.","lezione-4-1.html"],"lemaitre-georges":["Georges Lemaître (1894–1966) fu un fisico e astronomo belga che sviluppò un’interpretazione dell’espansione cosmica nella relatività generale e un’ipotesi sull’origine dell’Universo.","lezione-6-5.html"],"lente-gravitazionale":["Una lente gravitazionale modifica il cammino della luce per effetto della gravità della materia interposta. Può produrre distorsioni, immagini multiple e amplificazione di una sorgente più lontana.","lezione-6-4.html"],"lente-ottica":["Una lente ottica è un elemento trasparente che modifica la propagazione della luce per rifrazione e può contribuire a formare immagini.","lezione-7-3.html"],"leptone":["I leptoni sono una famiglia di particelle elementari che non partecipano all’interazione forte: comprendono elettrone, muone, tau e i rispettivi neutrini, con le antiparticelle.","lezione-10-4.html"],"librazione":["La librazione fa variare la parte della superficie lunare visibile dalla Terra, pur restando la Luna in rotazione sincrona in media.","lezione-2-5.html"],"limite-chandrasekhar":["Il limite di Chandrasekhar è la massa massima di equilibrio di una nana bianca nel modello sostenuto dalla pressione degli elettroni degeneri, circa 1,4 masse solari per composizioni comuni.","lezione-4-6.html"],"limite-eddington":["Il limite di Eddington è una luminosità di riferimento ottenuta confrontando l’azione della radiazione sulla materia con l’attrazione gravitazionale, sotto ipotesi specificate.","lezione-10-3.html"],"limite-roche":["Il limite di Roche descrive una distanza critica, dipendente dal modello, entro la quale le maree di un corpo possono disgregare un satellite sostenuto principalmente dalla propria gravità.","lezione-3-4.html"],"linea-di-vista":["La linea di vista è la direzione che collega l’osservatore al punto o all’oggetto osservato. Serve a distinguere proiezione apparente e posizione tridimensionale.","lezione-1-4.html"],"linea-neve":["La linea della neve è una regione di transizione in un disco protoplanetario oltre la quale una determinata sostanza volatile può trovarsi stabilmente in forma di ghiaccio nelle condizioni locali.","lezione-3-6.html"],"linearita-sensore":["La linearità descrive quanto la risposta misurata di un sensore sia proporzionale al segnale luminoso ricevuto, entro un intervallo operativo specificato.","astrofotografia.html"],"litio":["Il litio è l’elemento di numero atomico 3, simbolo Li. Le sue abbondanze e trasformazioni collegano la chimica cosmica alla storia delle stelle e dell’Universo.","lezione-4-6.html"],"litosfera":["La litosfera è l’involucro esterno relativamente rigido di un corpo roccioso; sulla Terra comprende la crosta e una porzione superiore del mantello.","lezione-3-2.html"],"livella":["Una livella permette di controllare l’orientamento di una superficie rispetto all’orizzontale locale; in astronomia pratica aiuta a preparare basi e supporti.","strumentazione.html"],"livello-energetico":["Un livello energetico è un valore di energia ammesso per uno stato di un sistema fisico; negli atomi e nelle molecole i livelli aiutano a interpretare gli spettri.","lezione-4-3.html"],"longitudine":["La longitudine geografica misura la posizione angolare di un luogo a est o a ovest di un meridiano di riferimento, convenzionalmente Greenwich.","lezione-9-3.html"],"lowell-percival":["Percival Lowell (1855–1916) fu un astronomo statunitense che fondò l’osservatorio di Flagstaff e sostenne un’interpretazione dei presunti canali marziani oggi superata.","lezione-3-2.html"],"luce":["Nel senso ottico la luce è la radiazione elettromagnetica visibile; in astronomia il termine viene talvolta esteso a bande che l’occhio non percepisce.","lezione-4-3.html"],"luce-bianca":["La luce bianca è una radiazione la cui combinazione spettrale produce una sensazione visiva di bianco nelle condizioni considerate; non è una singola lunghezza d’onda.","lezione-4-3.html"],"luce-cinerea":["La luce cinerea è il debole chiarore della parte lunare in notte, illuminata dalla luce solare riflessa dalla Terra verso la Luna.","lezione-2-4.html"],"luce-monocromatica":["Una radiazione monocromatica ideale possiede una sola frequenza; nei sistemi reali il termine indica spesso una banda molto stretta rispetto al problema studiato.","lezione-4-3.html"],"luce-parassita":["La luce parassita è radiazione indesiderata che raggiunge il rivelatore o l’occhio attraverso percorsi diversi da quelli utili alla formazione dell’immagine.","strumentazione.html"],"luce-zodiacale":["La luce zodiacale è il debole chiarore prodotto dalla luce solare diffusa da polveri interplanetarie, osservabile in condizioni favorevoli lungo la regione dell’eclittica.","lezione-8-5.html"],"lumen":["Il lumen, simbolo lm, è l’unità SI del flusso luminoso, una misura della radiazione pesata secondo la risposta visiva fotopica convenzionale.","lezione-7-5.html"],"luminosita":["In astronomia la luminosità intrinseca è la potenza radiativa emessa da una sorgente, nell’intero spettro o in una banda specificata.","lezione-4-2.html"],"luminosita-solare":["La luminosità solare esprime la potenza radiativa del Sole ed è usata anche come riferimento per confrontare l’emissione delle stelle.","lezione-4-2.html"],"luna":["La Luna è il satellite naturale della Terra; luce riflessa, moto orbitale e superficie producono fenomeni diversi che vanno distinti.","lezione-2-4.html"],"luna-16":["Luna 16 fu una missione robotica sovietica che nel 1970 riportò sulla Terra un campione di materiale lunare.","lezione-2-5.html"],"luna-2":["Sonda sovietica che nel 1959 diventò il primo manufatto umano a raggiungere la superficie lunare.","lezione-3-4.html"],"luna-3":["Sonda sovietica che nel 1959 trasmise le prime fotografie della faccia lontana della Luna.","lezione-3-4.html"],"lune-galileiane":["Le lune galileiane sono Io, Europa, Ganimede e Callisto, i quattro maggiori satelliti naturali di Giove, osservati da Galileo nel 1610.","lezione-3-4.html"],"lunghezza-d-onda":["La lunghezza d’onda è la distanza fra due punti consecutivi nella stessa fase di un’onda, per esempio due creste; si indica spesso con la lettera greca lambda, λ.","lezione-4-3.html"],"lunokhod-1":["Lunokhod 1 fu un rover sovietico portato sulla Luna da Luna 17 nel novembre 1970, fra i primi grandi successi dell’esplorazione robotica mobile.","lezione-10-5.html"],"lux":["Il lux, simbolo lx, è l’unità SI dell’illuminamento: un lux equivale a un lumen incidente per metro quadrato.","lezione-7-5.html"],"magellan":["Magellan fu una missione NASA che utilizzò il radar dall’orbita per mappare gran parte della superficie di Venere negli anni Novanta.","lezione-3-2.html"],"magnesio":["Il magnesio è l’elemento chimico di numero atomico 12 e simbolo Mg, presente in numerosi minerali e riconoscibile negli spettri astronomici.","lezione-3-2.html"],"magnetar":["Una magnetar è una stella di neutroni con campo magnetico estremamente intenso, la cui evoluzione magnetica può alimentare emissioni e improvvisi eventi energetici.","lezione-10-3.html"],"magnetopausa":["La magnetopausa è il confine della magnetosfera, determinato dall’interazione fra il campo del corpo e il plasma esterno. Per la Terra dipende dalle condizioni del vento solare.","lezione-8-3.html"],"magnetosfera":["La magnetosfera è la regione nella quale il campo magnetico di un corpo celeste governa in modo importante la dinamica del plasma, interagendo con l’ambiente esterno.","lezione-8-3.html"],"magnitudine-apparente":["Numero che descrive quanto un astro appare brillante in una determinata banda: valori più piccoli indicano maggiore brillantezza.","lezione-4-2.html"],"magnitudine-assoluta":["Magnitudine che un oggetto avrebbe se fosse osservato dalla distanza convenzionale di 10 parsec, nella banda specificata.","lezione-4-2.html"],"magnitudine-bolometrica":["La magnitudine bolometrica esprime, nella scala delle magnitudini, il contributo complessivo della radiazione considerata su tutto lo spettro.","lezione-4-2.html"],"magnitudine-limite":["La magnitudine limite indica la brillantezza più debole rilevabile secondo un criterio e condizioni dichiarati. Non è una proprietà fissa del solo telescopio.","lezione-7-6.html"],"manganese":["Il manganese è l’elemento chimico di simbolo Mn e numero atomico 25; il suo sistema isotopico con il cromo è utile per ricostruire la storia di materiali planetari.","lezione-3-1.html"],"mantello-planetario":["Il mantello è la regione interna di un corpo roccioso differenziato compresa tra crosta e nucleo; il suo stato dipende da composizione, temperatura e pressione.","lezione-3-2.html"],"mare-lunare":["Un mare lunare è una vasta regione prevalentemente basaltica della superficie della Luna, spesso più scura degli altopiani circostanti.","lezione-2-5.html"],"marea":["Le maree sono risposte alla differenza del campo gravitazionale attraverso un corpo; sulla Terra producono oscillazioni marine la cui forma dipende anche dai bacini e dalle coste.","lezione-3-4.html"],"mariner-10":["Mariner 10 fu una sonda NASA lanciata nel 1973 che sorvolò Venere e Mercurio, aprendo l’esplorazione ravvicinata di Mercurio.","lezione-10-5.html"],"mariner-4":["Mariner 4 fu la sonda NASA che nel luglio 1965 sorvolò Marte e trasmise le prime immagini ravvicinate riuscite del pianeta.","lezione-10-5.html"],"mariner-9":["Mariner 9 è la sonda NASA che nel novembre 1971 entrò in orbita attorno a Marte, permettendo uno studio ripetuto del pianeta invece di un solo sorvolo.","lezione-10-5.html"],"mars-express":["Mars Express è una missione dell’ESA lanciata nel 2003 per studiare Marte dall’orbita, con osservazioni della superficie, dell’atmosfera e del sottosuolo.","lezione-3-2.html"],"marte":["Marte è il quarto pianeta dal Sole, un pianeta roccioso con atmosfera tenue, superficie ricca di tracce geologiche e due piccoli satelliti.","lezione-3-2.html"],"maschera-bahtinov":["La maschera di Bahtinov è un accessorio a fenditure che produce una figura di diffrazione utile per controllare la messa a fuoco sulle stelle.","astrofotografia.html"],"maser":["Un maser amplifica radiazione attraverso emissione stimolata, tipicamente nelle microonde. Maser naturali possono formarsi in ambienti astronomici con condizioni appropriate.","lezione-4-3.html"],"massa":["La massa caratterizza la risposta di un corpo alle forze e il suo ruolo gravitazionale; non coincide con il peso né con il volume.","lezione-4-1.html"],"massa-atomica-relativa":["La massa atomica relativa è il rapporto fra una massa atomica, o una media appropriata di masse atomiche, e l’unità di massa atomica unificata. È un numero senza unità.","lezione-10-4.html"],"massa-d-aria":["In astronomia la massa d’aria esprime il cammino atmosferico attraversato dalla luce rispetto a un cammino di riferimento, generalmente quello verso lo zenit.","lezione-7-5.html"],"massa-molare":["La massa molare è il rapporto fra la massa di un campione e la sua quantità di sostanza; nel SI si esprime in chilogrammi per mole.","lezione-4-1.html"],"massa-solare":["La massa solare è un riferimento usato per esprimere masse astronomiche come multipli della massa del Sole. Si indica spesso con M☉.","lezione-4-1.html"],"materia-oscura":["La materia oscura è una componente di materia inferita dai suoi effetti gravitazionali, che non viene identificata attraverso la normale emissione luminosa della materia stellare e del gas.","lezione-6-4.html"],"maxwell-james":["James Clerk Maxwell (1831–1879) fu un fisico scozzese che unificò la descrizione classica di elettricità, magnetismo e luce.","lezione-4-3.html"],"media-aritmetica":["La media aritmetica si ottiene sommando i valori e dividendo il totale per il numero di valori. Riassume una posizione centrale, ma non descrive da sola la distribuzione.","lezione-9-4.html"],"mediana":["La mediana è un valore che divide una distribuzione ordinata in due parti con uguale numerosità; per un campione pari si usa comunemente la media dei due valori centrali.","lezione-9-4.html"],"mendeleev-dmitrij":["Dmitrij Mendeleev (1834–1907) fu un chimico fondamentale per la costruzione del sistema periodico degli elementi.","lezione-10-2.html"],"mercurio":["Mercurio è il pianeta più vicino al Sole e il più piccolo degli otto pianeti del Sistema solare.","lezione-3-2.html"],"meridiano":["Il meridiano celeste locale è il grande cerchio che passa per i poli celesti e lo zenit dell’osservatore; sulla Terra i meridiani servono a definire le longitudini.","lezione-1-3.html"],"mese-anomalistico":["Il mese anomalistico è l’intervallo fra due passaggi successivi della Luna al perigeo. Il suo valore medio è circa 27,55 giorni.","lezione-2-4.html"],"mese-draconitico":["Il mese draconitico, o draconico, è l’intervallo fra due passaggi successivi della Luna attraverso lo stesso nodo dell’orbita. Dura in media circa 27,21 giorni.","lezione-2-6.html"],"mese-siderale":["Il mese siderale è il periodo medio della rivoluzione lunare rispetto a un riferimento stellare, pari a circa 27,32 giorni.","lezione-2-4.html"],"mese-sinodico":["Il mese sinodico è il tempo medio che separa due configurazioni lunari equivalenti rispetto al Sole, come due Lune nuove consecutive. Dura circa 29 giorni e mezzo.","lezione-2-4.html"],"messenger":["MESSENGER fu una missione NASA che studiò Mercurio dall’orbita fra il 2011 e il 2015, ampliando la conoscenza ottenuta dai precedenti sorvoli.","lezione-3-2.html"],"messier-catalogo":["Il catalogo di Messier raccoglie oggetti celesti dall’aspetto diffuso o non stellare, identificati oggi con sigle da M1 a M110 nella lista usuale.","lezione-9-4.html"],"metallicita":["In astronomia la metallicità descrive l’abbondanza degli elementi più pesanti di idrogeno ed elio, chiamati convenzionalmente metalli.","lezione-4-3.html"],"metallo-alcalino":["I metalli alcalini sono gli elementi metallici del gruppo 1 della tavola periodica; l’idrogeno, pur collocato nella stessa colonna, non appartiene a questa famiglia metallica.","lezione-10-2.html"],"metallo-alcalino-terroso":["I metalli alcalino-terrosi sono gli elementi del gruppo 2 della tavola periodica, come magnesio, calcio e bario.","lezione-10-2.html"],"metallo-transizione":["Un elemento di transizione ha un sottolivello d incompleto nell’atomo oppure può formare cationi con un sottolivello d incompleto, secondo la definizione IUPAC.","lezione-10-2.html"],"metano":["Il metano, CH₄, è il più semplice idrocarburo: una molecola contiene un atomo di carbonio e quattro di idrogeno. È presente in diversi ambienti planetari.","lezione-3-3.html"],"metanolo":["Il metanolo, CH₃OH, è l’alcol più semplice. In astrochimica viene studiato come molecola organica e come traccia dei processi che coinvolgono ghiacci, polvere e gas.","lezione-4-5.html"],"meteora":["Fenomeno luminoso atmosferico provocato dall’ingresso di un meteoroide.","lezione-8-1.html"],"meteorite":["Materiale di origine cosmica che raggiunge la superficie di un pianeta o satellite.","lezione-8-1.html"],"meteoroide":["Piccolo corpo solido nello spazio interplanetario che può produrre una meteora entrando nell’atmosfera.","lezione-8-1.html"],"metro-unita":["Il metro, simbolo m, è l’unità SI della lunghezza, definita fissando la velocità della luce nel vuoto e usando il secondo.","lezione-6-3.html"],"microlente-gravitazionale":["La microlente gravitazionale è un effetto di lente in cui la deviazione della luce produce segnali osservabili, spesso variazioni di luminosità, senza separare normalmente le immagini multiple con l’osservazione ordinaria.","lezione-10-1.html"],"micrometro":["Il micrometro, simbolo μm, è un milionesimo di metro, ossia un millesimo di millimetro e mille nanometri.","astrofotografia.html"],"migrazione-planetaria":["La migrazione planetaria è una variazione dell’orbita di un pianeta dovuta a scambi di energia e momento angolare con altri componenti del sistema.","lezione-3-6.html"],"modulo-vettore":["Il modulo di un vettore è la quantità scalare non negativa che ne esprime la grandezza, distinta da direzione e verso.","lezione-3-6.html"],"mole":["La mole, simbolo mol, è l’unità SI della quantità di sostanza: una mole contiene esattamente 6,02214076 × 10²³ entità specificate.","lezione-4-1.html"],"molecola":["Una molecola è un’entità formata da più atomi legati, con struttura e proprietà proprie; nel linguaggio specialistico una specie molecolare carica viene specificata come ione molecolare.","lezione-5-4.html"],"momento-angolare":["Il momento angolare è una grandezza vettoriale che descrive lo stato di moto rotazionale rispetto a un punto o asse di riferimento; la sua conservazione è centrale nella dinamica celeste.","lezione-4-5.html"],"momento-forza":["Il momento di una forza descrive la sua azione rotazionale rispetto a un punto o asse. Dipende dalla forza e dal suo braccio, cioè dalla geometria della retta d’azione.","lezione-7-6.html"],"momento-inerzia":["Il momento d’inerzia descrive come la massa è distribuita rispetto a un asse di rotazione e quanto il corpo resiste, nel modello considerato, a variazioni della rotazione attorno a quell’asse.","lezione-7-6.html"],"monossido-carbonio":["Il monossido di carbonio, formula CO, è una molecola composta da un atomo di carbonio e uno di ossigeno, molto utilizzata nello studio del gas molecolare astronomico.","lezione-4-5.html"],"montatura-a-forcella":["Una montatura a forcella sostiene il tubo fra due bracci. La forma del supporto non determina da sola se il sistema sia altazimutale o equatoriale.","strumentazione.html"],"montatura-altazimutale":["Un supporto altazimutale orienta lo strumento con un movimento in azimut e uno in altezza rispetto all’orizzonte locale.","lezione-7-3.html"],"montatura-equatoriale":["Una montatura equatoriale dispone l’asse polare parallelamente all’asse terrestre e un secondo asse, di declinazione, perpendicolare al primo.","lezione-7-3.html"],"mosaico-astronomico":["Un mosaico astronomico combina riprese di campi parzialmente sovrapposti per rappresentare una regione più ampia di quella coperta da una singola immagine.","astrofotografia.html"],"moto-circolare":["Il moto circolare è un moto la cui traiettoria è una circonferenza rispetto al riferimento scelto; anche a rapidità costante comporta un cambiamento della direzione della velocità.","lezione-3-6.html"],"moto-proprio":["Il moto proprio è la variazione della direzione di una stella nel tempo, dovuta al suo moto relativo rispetto al sistema di riferimento adottato. Si esprime come angolo per unità di tempo.","lezione-1-4.html"],"nadir":["Il nadir è la direzione della verticale verso il basso per un osservatore, opposta allo zenit sulla sfera celeste.","lezione-1-1.html"],"nana-bianca":["Una nana bianca è un residuo stellare compatto, sostenuto soprattutto dalla pressione degli elettroni degeneri. Rappresenta il destino finale di molte stelle, comprese quelle simili al Sole.","lezione-4-6.html"],"nana-bruna":["Una nana bruna è un oggetto substellare che non sostiene stabilmente la fusione dell’idrogeno come una stella ordinaria. Le sue proprietà cambiano con massa, età e composizione.","lezione-4-4.html"],"nana-rossa":["Una nana rossa è una stella di piccola massa, relativamente fredda e poco luminosa, che mantiene la fusione dell’idrogeno sulla sequenza principale.","lezione-4-4.html"],"nanometro":["Il nanometro, simbolo nm, è un’unità di lunghezza pari a un miliardesimo di metro.","lezione-4-3.html"],"nebulosa":["Concentrazione di gas e polveri dall’aspetto diffuso, luminosa oppure scura sul fondo del cielo.","lezione-5-4.html"],"nebulosa-a-emissione":["Nube il cui gas emette radiazione dopo essere stato eccitato o ionizzato.","lezione-5-4.html"],"nebulosa-a-riflessione":["Nube le cui polveri diffondono la luce di stelle vicine.","lezione-5-4.html"],"nebulosa-oscura":["Nube che attenua la luce delle sorgenti retrostanti e appare scura rispetto allo sfondo.","lezione-5-4.html"],"nebulosa-planetaria":["Una nebulosa planetaria è un involucro di gas espulso da una stella evoluta e reso luminoso dalla radiazione della sorgente centrale molto calda. Il nome non indica una nube che forma pianeti.","lezione-5-5.html"],"neon":["Il neon è l’elemento di numero atomico 10, simbolo Ne, appartenente ai gas nobili. In astronomia viene riconosciuto attraverso firme spettrali anche nei gas ionizzati.","lezione-5-5.html"],"nettuno":["Nettuno è l’ottavo pianeta dal Sole, un gigante di ghiaccio con atmosfera dinamica, anelli e satelliti.","lezione-3-3.html"],"neutrino":["Il neutrino è una particella elementare elettricamente neutra, di massa molto piccola e interazione debole con la materia.","lezione-4-1.html"],"neutrino-solare":["Un neutrino solare è un neutrino prodotto in processi nucleari del Sole, capace di fornire informazioni sulle reazioni che avvengono al suo interno.","lezione-2-3.html"],"neutrone":["Il neutrone è una particella composta, priva di carica elettrica complessiva, che insieme al protone costituisce molti nuclei atomici.","lezione-4-1.html"],"new-horizons":["New Horizons è la sonda NASA che sorvolò Plutone e le sue lune nel 2015 e il corpo della fascia di Kuiper Arrokoth nel 2019.","lezione-3-5.html"],"newton-isaac":["Isaac Newton (1643–1727, date gregoriane) sviluppò un quadro matematico della dinamica e della gravitazione, collegando il moto dei corpi terrestri a quello dei corpi celesti.","lezione-3-6.html"],"newton-unita":["Il newton, simbolo N, è l’unità SI della forza: nel quadro della meccanica classica, un newton accelera un chilogrammo di un metro al secondo ogni secondo.","lezione-3-6.html"],"newtoniano":["Il telescopio newtoniano usa uno specchio primario concavo e uno specchio secondario piano per portare l’immagine lateralmente verso il fuoco.","lezione-7-3.html"],"ngc":["NGC è la sigla di New General Catalogue, repertorio storico di nebulose e ammassi che identifica oggi molti oggetti del cielo profondo.","lezione-9-4.html"],"nichel":["Il nichel è l’elemento chimico di numero atomico 28 e simbolo Ni, presente in leghe meteoriche e importante anche nella storia nucleare delle supernovae.","lezione-4-6.html"],"nitrile":["I nitrili sono composti che contengono un gruppo carbonio-azoto con triplo legame, collegato a un gruppo organico.","lezione-10-2.html"],"nodo-orbitale":["Un nodo orbitale è un punto nel quale un’orbita interseca un piano di riferimento; si distingue fra nodo ascendente e discendente secondo il verso di attraversamento.","lezione-2-6.html"],"nomenclatura-stock":["La nomenclatura con numero di ossidazione, spesso insegnata come nomenclatura di Stock, distingue composti indicando con un numero romano lo stato di ossidazione di un elemento.","lezione-5-4.html"],"nova":["Una nova è un forte aumento di luminosità associato, nel caso classico, a un episodio termonucleare nello strato accumulato sulla superficie di una nana bianca in un sistema binario.","lezione-4-6.html"],"nube-di-oort":["La nube di Oort è una popolazione molto lontana di corpi minori, inferita soprattutto dalle proprietà delle comete di lungo periodo e dalla dinamica del Sistema solare.","lezione-3-5.html"],"nube-molecolare":["Una nube molecolare è una regione del mezzo interstellare nella quale una parte importante del gas, soprattutto idrogeno, si trova in forma molecolare.","lezione-4-5.html"],"nucleo-atomico":["Il nucleo atomico è la regione centrale dell’atomo che contiene protoni e, nella maggior parte degli isotopi ordinari, neutroni, concentrandone quasi tutta la massa.","lezione-4-3.html"],"nucleo-cometario":["Il nucleo cometario è il corpo solido di una cometa, composto da materiali refrattari e sostanze volatili, dal quale può svilupparsi l’attività di chioma e code.","lezione-3-5.html"],"nucleo-galattico-attivo":["Un nucleo galattico attivo è una regione centrale compatta con forte emissione alimentata principalmente dall’accrescimento di materia attorno a un buco nero supermassiccio.","lezione-6-2.html"],"nucleo-planetario":["Il nucleo planetario è la regione centrale di un corpo differenziato, generalmente arricchita nei componenti più densi rispetto agli involucri esterni.","lezione-3-2.html"],"nucleone":["Nucleone è il nome collettivo di protone e neutrone, le particelle che costituiscono i nuclei atomici ordinari.","lezione-4-1.html"],"nucleosintesi":["La nucleosintesi comprende i processi che formano nuclei atomici, dalla storia primordiale dell’Universo all’evoluzione stellare e agli eventi energetici.","lezione-4-6.html"],"nuclide":["Un nuclide è una specie nucleare identificata dal numero di protoni e neutroni; quando necessario si specifica anche lo stato energetico nucleare.","lezione-4-6.html"],"numero-atomico":["Il numero atomico, indicato con Z, conta i protoni del nucleo e identifica l’elemento chimico.","lezione-4-3.html"],"numero-coordinazione":["Il numero di coordinazione indica quanti vicini o legami di coordinazione circondano un centro, secondo il contesto strutturale e la definizione adottata.","lezione-10-2.html"],"numero-di-massa":["Il numero di massa A è il numero complessivo di protoni e neutroni presenti in un nucleo atomico.","lezione-4-3.html"],"numero-neutroni":["Il numero di neutroni, indicato con N, è il conteggio dei neutroni presenti in un nucleo atomico ed è uguale al numero di massa meno il numero atomico.","lezione-10-4.html"],"numero-ossidazione":["Il numero di ossidazione è un valore formale attribuito a un atomo con regole di assegnazione degli elettroni di legame. Aiuta a descrivere composti e reazioni senza coincidere sempre con una carica reale localizzata.","lezione-3-2.html"],"numero-quantico":["Un numero quantico è un valore che identifica una proprietà di uno stato quantistico nel modello e nelle condizioni considerati.","lezione-4-3.html"],"numero-quantico-principale":["Il numero quantico principale, indicato con n, assume valori interi positivi e contribuisce a classificare gli stati elettronici atomici.","lezione-4-3.html"],"nutazione":["La nutazione terrestre è l’insieme di piccole variazioni periodiche dell’orientamento dell’asse, sovrapposte al cambiamento più lento descritto dalla precessione.","lezione-1-6.html"],"obiettivo":["Sistema ottico che raccoglie la luce e forma l’immagine dell’oggetto osservato. Può utilizzare lenti, specchi o entrambi.","lezione-7-3.html"],"occiduo":["Nel contesto del moto diurno, astro che sorge e tramonta rispetto all’orizzonte del luogo.","lezione-1-3.html"],"occultazione":["Un’occultazione avviene quando un corpo celeste passa davanti a un altro lungo la linea di vista dell’osservatore e ne nasconde tutta o parte della luce.","lezione-9-3.html"],"oculare":["L’oculare è il gruppo ottico attraverso cui l’occhio osserva l’immagine formata dal telescopio; non è l’elemento principale che raccoglie luce.","lezione-7-4.html"],"ohm":["L’ohm, simbolo Ω, è l’unità SI della resistenza elettrica e si usa anche per impedenza e reattanza; un ohm equivale a un volt per ampere.","strumentazione.html"],"olivina":["L’olivina è un gruppo di silicati la cui composizione comprende comunemente magnesio e ferro, importante nelle rocce dei pianeti e nei meteoriti.","lezione-3-2.html"],"omogeneita-cosmologica":["L’omogeneità cosmologica è l’ipotesi che, su scale sufficientemente grandi e a una data epoca, le proprietà medie dell’Universo non dipendano dalla posizione.","lezione-6-4.html"],"onda-gravitazionale":["Un’onda gravitazionale è una perturbazione della geometria dello spazio-tempo che si propaga e può trasportare energia lontano dalla sorgente.","lezione-10-3.html"],"opacita":["L’opacità descrive quanto un materiale ostacoli la propagazione della radiazione considerata; in astrofisica si usano coefficienti definiti per banda e condizioni del mezzo.","lezione-5-4.html"],"opposizione":["Nella convenzione eclittica geocentrica, l’opposizione al Sole corrisponde a una differenza di 180° di longitudine celeste.","lezione-9-3.html"],"ora-civile":["L’ora civile è l’ora adottata per la vita quotidiana in un territorio: nei dati astronomici va specificata insieme a data e fuso.","lezione-9-3.html"],"ora-legale":["L’ora legale estiva è un anticipo convenzionale dell’orario civile rispetto all’ora standard; nel sistema italiano CET/CEST la differenza è un’ora.","guide.html"],"ora-solare-vera":["L’ora solare vera, o apparente, descrive il tempo attraverso la posizione del Sole vero rispetto al meridiano locale; il mezzogiorno corrisponde al suo passaggio superiore.","guide.html"],"orbita":["Traiettoria percorsa da un corpo attorno a un altro sotto l’azione della gravità.","lezione-3-1.html"],"orbita-geostazionaria":["Un’orbita geostazionaria ideale è circolare, equatoriale e prograda, con periodo uguale al giorno siderale terrestre: il satellite mantiene la stessa direzione rispetto al suolo.","lezione-10-5.html"],"orbita-polare":["Un’orbita polare ideale ha il piano contenente l’asse di rotazione del corpo centrale e inclinazione di circa 90° rispetto al suo equatore.","lezione-10-5.html"],"orbitale-atomico":["Un orbitale atomico è una funzione usata per descrivere lo stato spaziale di un elettrone nell’atomo, non una traiettoria percorsa intorno al nucleo.","lezione-4-3.html"],"orbiter":["Un orbiter è un veicolo spaziale progettato per studiare un corpo celeste percorrendo un’orbita attorno a esso. Il nome distingue questa modalità dal semplice sorvolo e dalla discesa sulla superficie.","lezione-10-5.html"],"orion-capsula":["Veicolo progettato per trasportare astronauti oltre l’orbita terrestre bassa.","lezione-3-4.html"],"orizzonte":["Il piano astronomico locale perpendicolare alla verticale dell’osservatore. Il profilo visibile di monti e case è un riferimento diverso.","lezione-1-1.html"],"orizzonte-degli-eventi":["Per un buco nero, l’orizzonte degli eventi è il confine dello spazio-tempo oltre il quale segnali diretti verso l’esterno non possono raggiungere osservatori lontani.","lezione-10-3.html"],"oscillazioni-acustiche-barioniche":["Le oscillazioni acustiche barioniche, o BAO, sono la traccia di oscillazioni nel plasma primordiale, riconoscibile statisticamente nella distribuzione della materia su grandi scale.","lezione-6-4.html"],"oscuramento-al-bordo":["L’oscuramento al bordo è la diminuzione della brillantezza apparente verso il margine del disco di una stella, evidente per il Sole in molte bande del visibile.","lezione-2-3.html"],"osiris-rex":["OSIRIS-REx è la missione NASA che raccolse materiale dall’asteroide Bennu e ne riportò un campione sulla Terra nel settembre 2023.","lezione-10-5.html"],"ossidoriduzione":["Un’ossidoriduzione è una trasformazione chimica nella quale cambiano gli stati di ossidazione: all’ossidazione di una specie si accompagna la riduzione di un’altra.","lezione-3-2.html"],"ossigeno":["L’ossigeno è l’elemento di numero atomico 8 e simbolo O, presente in gas, acqua, ghiacci e molti minerali.","lezione-10-2.html"],"ottica-adattiva":["L’ottica adattiva misura e corregge rapidamente deformazioni del fronte d’onda, per ridurre soprattutto il degrado delle immagini causato dalla turbolenza atmosferica.","lezione-7-5.html"],"ottica-attiva":["L’ottica attiva controlla forma e allineamento delle superfici ottiche per compensare deformazioni relativamente lente del telescopio.","strumentazione.html"],"otturatore":["In fotografia l’otturatore e il controllo elettronico dell’esposizione regolano l’intervallo durante il quale viene registrato il segnale di una ripresa.","astrofotografia.html"],"parallasse":["Variazione apparente della direzione di un oggetto quando cambia il punto di osservazione.","lezione-6-3.html"],"paraluce":["Un paraluce è uno schermo attorno all’apertura ottica che limita l’arrivo di luce indesiderata da direzioni esterne al campo utile.","strumentazione.html"],"paramagnetismo":["Il paramagnetismo è una risposta della materia che produce una magnetizzazione nel verso del campo applicato, senza la tipica magnetizzazione permanente di un ferromagnete.","lezione-10-2.html"],"parker-solar-probe":["Parker Solar Probe è una sonda della NASA progettata per attraversare regioni della corona solare e studiare particelle, campi magnetici e origine del vento solare.","lezione-2-3.html"],"parsec":["Unità di distanza definita attraverso una parallasse annua di un secondo d’arco; equivale a circa 3,26 anni luce.","lezione-6-3.html"],"particella-alfa":["Una particella alfa è un nucleo di elio-4, formato da due protoni e due neutroni, con carica elettrica positiva pari a due cariche elementari.","lezione-10-4.html"],"pascal-unita":["Il pascal, simbolo Pa, è l’unità SI della pressione: un pascal corrisponde a un newton di forza normale distribuito su un metro quadrato.","lezione-3-2.html"],"pauli-esclusione":["Il principio di esclusione di Pauli impedisce a due fermioni identici di occupare lo stesso stato quantistico completo.","lezione-4-6.html"],"payne-cecilia":["Cecilia Payne-Gaposchkin (1900–1979) fu un’astrofisica il cui lavoro del 1925 collegò la fisica degli spettri alla forte abbondanza di idrogeno ed elio nelle stelle.","lezione-4-3.html"],"penombra":["La penombra è la regione nella quale un corpo opaco nasconde soltanto una parte di una sorgente luminosa estesa.","lezione-2-6.html"],"perielio":["Il perielio è il punto di un’orbita attorno al Sole in cui la distanza dal Sole è minima.","lezione-3-6.html"],"perigeo":["Il perigeo è il punto di un’orbita attorno alla Terra in cui la distanza dalla Terra è minima.","lezione-2-4.html"],"periodo-chimico":["Un periodo è una riga della tavola periodica, nella quale gli elementi sono disposti in ordine di numero atomico crescente.","lezione-4-3.html"],"periodo-orbitale":["Il periodo orbitale è il tempo necessario a completare un ciclo del moto orbitale rispetto al riferimento specificato.","lezione-3-6.html"],"periodo-pulsazione":["Il periodo di pulsazione stellare è l’intervallo caratteristico di ripetizione di un’oscillazione fisica della stella, riconoscibile attraverso misure appropriate.","lezione-4-2.html"],"periodo-sinodico":["Il periodo sinodico è l’intervallo fra due successive configurazioni equivalenti di un corpo rispetto all’osservatore e al Sole, come due opposizioni di un pianeta esterno.","lezione-3-6.html"],"permafrost":["Il permafrost è terreno che rimane a temperatura non superiore a zero gradi Celsius per almeno due anni consecutivi. La definizione è termica e non richiede necessariamente ghiaccio.","lezione-3-2.html"],"perturbazione-orbitale":["Una perturbazione orbitale è una variazione rispetto a un moto orbitale di riferimento, prodotta da interazioni o effetti aggiuntivi inclusi nel modello.","lezione-3-6.html"],"peso":["Il peso è una forza legata alla gravità locale; nel modello introduttivo vicino alla superficie di un corpo si scrive P = m × g, distinguendolo dalla massa.","lezione-3-6.html"],"ph":["Il pH esprime l’acidità attraverso una scala legata all’attività degli ioni idrogeno; nelle soluzioni diluite si può usare come approssimazione la loro concentrazione.","lezione-10-2.html"],"phobos":["Phobos è il maggiore dei due piccoli satelliti di Marte, un corpo irregolare che orbita molto vicino al pianeta.","lezione-3-4.html"],"pianeta":["Nel Sistema solare: corpo in orbita intorno al Sole, quasi sferico per la propria gravità e dinamicamente dominante nella sua zona orbitale.","lezione-3-1.html"],"pianeta-nano":["Nella definizione IAU per il Sistema solare, un pianeta nano orbita attorno al Sole, ha una forma quasi rotonda per la propria gravità, non ha ripulito la regione della sua orbita e non è un satellite.","lezione-3-5.html"],"pianetesimo":["Un pianetesimo è un corpo solido formato durante le prime fasi della crescita planetaria, capace di partecipare all’accrescimento e all’evoluzione dinamica del sistema.","lezione-3-6.html"],"piano-focale":["Il piano focale è il riferimento in cui un sistema ottico forma l’immagine a fuoco nel modello considerato. Nei sistemi reali la superficie di miglior fuoco può essere curva.","astrofotografia.html"],"piano-orbitale":["Il piano orbitale contiene il moto di un’orbita kepleriana ideale; in sistemi perturbati si usa spesso un piano istantaneo associato all’orbita osculatrice.","lezione-3-6.html"],"pioneer-10":["Pioneer 10 fu una sonda NASA lanciata nel 1972 e protagonista del primo incontro ravvicinato con Giove nel 1973, aprendo l’esplorazione dei pianeti esterni.","lezione-10-5.html"],"pirosseno":["I pirosseni sono un gruppo di minerali silicatici con strutture a catena, frequenti nelle rocce magmatiche e importanti nello studio di superfici planetarie e meteoriti.","lezione-3-2.html"],"pixel":["Il pixel è un elemento di un’immagine digitale; nel contesto del sensore va distinto dal modo in cui l’immagine viene visualizzata o ricampionata.","astrofotografia.html"],"planck-max":["Max Planck (1858–1947) fu il fisico che nel 1900 introdusse un’ipotesi di quantizzazione nello studio della radiazione del corpo nero, aprendo un passaggio decisivo verso la fisica quantistica.","lezione-4-3.html"],"planck-missione":["Planck fu una missione ESA dedicata soprattutto alla radiazione cosmica di fondo nelle microonde, con misure delle sue piccole variazioni e della polarizzazione.","lezione-6-5.html"],"planisfero-celeste":["Un planisfero celeste girevole è una carta con una maschera mobile che permette di individuare approssimativamente il cielo visibile a una certa data e ora, per una fascia di latitudine.","guide.html"],"plasma":["In fisica un plasma è un insieme di particelle con una componente significativa di cariche libere, capace di comportamenti collettivi elettromagnetici.","lezione-4-1.html"],"plate-solving":["Il plate solving, o risoluzione astrometrica, identifica il campo di una ripresa confrontando le posizioni delle stelle con cataloghi e ricava una corrispondenza fra pixel e coordinate celesti.","astrofotografia.html"],"plutone":["Plutone è un pianeta nano transnettuniano, visitato dalla sonda New Horizons durante il sorvolo del 2015.","lezione-3-5.html"],"polare":["La Polare, Alpha Ursae Minoris, è una stella dell’Orsa Minore vicina al polo nord celeste, utile come riferimento approssimativo per l’orientamento nell’emisfero boreale.","lezione-1-2.html"],"polarimetria":["La polarimetria misura lo stato di polarizzazione della radiazione, cioè proprietà legate all’orientamento e all’andamento dell’oscillazione del campo elettrico. Può rivelare informazioni sulla diffusione della luce e sulla geometria di sorgenti e materiali.","lezione-4-3.html"],"polarimetro":["Un polarimetro misura proprietà della polarizzazione della radiazione, distinguendo contributi che una sola misura di intensità non conserva.","lezione-4-3.html"],"polarizzazione":["La polarizzazione della luce descrive come si orienta e varia nel tempo il campo elettrico dell’onda elettromagnetica, e offre informazioni ulteriori rispetto alla sola intensità.","lezione-4-3.html"],"polimero":["Un polimero è una sostanza costituita da macromolecole la cui struttura comprende molte unità ripetute, derivate realmente o concettualmente da molecole più piccole.","lezione-10-2.html"],"polimorfismo-cristallino":["Il polimorfismo cristallino è la possibilità che una sostanza presenti strutture cristalline differenti.","lezione-3-2.html"],"polo-celeste":["Uno dei due punti in cui il prolungamento dell’asse di rotazione terrestre incontra la sfera celeste.","lezione-1-2.html"],"polvere-interplanetaria":["La polvere interplanetaria comprende piccoli grani solidi presenti nello spazio del Sistema solare, alimentati e modificati da diversi processi dinamici e fisici.","lezione-3-5.html"],"polvere-interstellare":["La polvere interstellare è costituita da piccoli grani solidi presenti fra le stelle, che assorbono, diffondono ed emettono radiazione e partecipano alla chimica del mezzo interstellare.","lezione-5-4.html"],"positrone":["Il positrone è l’antiparticella dell’elettrone: possiede la stessa massa e una carica elettrica positiva uguale in valore assoluto a quella dell’elettrone.","lezione-10-3.html"],"potassio":["Il potassio è l’elemento di numero atomico 19, simbolo K. Il suo isotopo radioattivo potassio-40 è importante per il calore interno dei corpi rocciosi e per alcuni metodi di datazione.","lezione-3-2.html"],"potenza-fisica":["La potenza indica l’energia trasferita o trasformata nell’unità di tempo; nel Sistema internazionale si misura in watt, equivalenti a joule al secondo.","lezione-4-2.html"],"potenziale-elettrico":["Il potenziale elettrico, nel quadro elettrostatico, è l’energia potenziale per unità di carica rispetto a un riferimento scelto. Si misura in volt.","strumentazione.html"],"precessione":["In astronomia la precessione comprende cambiamenti lenti dell’orientamento dei riferimenti terrestri e orbitali; la precessione dell’asse terrestre modifica nel tempo le direzioni dei poli celesti.","lezione-1-6.html"],"precisione-misura":["La precisione di misura riguarda la concordanza tra risultati ottenuti ripetendo misure sullo stesso oggetto, o su oggetti simili, in condizioni dichiarate.","lezione-9-4.html"],"pressione":["La pressione misura una forza normale distribuita su una superficie; nel Sistema internazionale si esprime in pascal, equivalenti a newton per metro quadrato.","lezione-4-1.html"],"pressione-degenerazione":["La pressione di degenerazione è un contributo quantistico alla pressione di un insieme di fermioni, legato al principio di esclusione di Pauli.","lezione-4-6.html"],"pressione-parziale":["La pressione parziale descrive il contributo di un componente di una miscela gassosa; nel modello ideale coincide con la pressione che quel gas eserciterebbe da solo nello stesso volume e alla stessa temperatura.","lezione-3-3.html"],"pressione-radiazione":["La pressione di radiazione è il trasferimento di quantità di moto della radiazione alla materia, descritto come forza per unità di area.","lezione-4-1.html"],"pressione-vapore":["La pressione di vapore saturo è la pressione esercitata dal vapore in equilibrio con una fase condensata a temperatura specificata.","lezione-3-5.html"],"principio-equivalenza":["Il principio di equivalenza collega localmente la descrizione della caduta libera e dei riferimenti accelerati agli effetti della gravità; è un fondamento della relatività generale.","lezione-10-3.html"],"principio-indeterminazione":["Il principio di indeterminazione pone limiti alle dispersioni congiunte di coppie di grandezze quantistiche, come posizione e quantità di moto, in uno stesso stato.","lezione-4-3.html"],"processo-r":["Il processo r è un percorso di nucleosintesi nel quale catture successive di neutroni avvengono rapidamente rispetto ai decadimenti beta dei nuclei coinvolti. La lettera r significa rapido.","lezione-10-4.html"],"processo-s":["Il processo s è un percorso di nucleosintesi per catture di neutroni relativamente lente rispetto ai decadimenti beta dei nuclei instabili incontrati. La lettera s richiama slow, lento.","lezione-4-6.html"],"prodotto-scalare":["Il prodotto scalare combina due vettori in un numero che dipende dai loro moduli e dal loro orientamento reciproco.","lezione-3-6.html"],"prodotto-vettoriale":["Il prodotto vettoriale combina due vettori in un nuovo vettore perpendicolare al piano individuato dai primi, con verso definito da una convenzione.","lezione-3-6.html"],"profondita-bit":["La profondità in bit indica quanti bit sono usati per rappresentare un valore digitale; nelle immagini contribuisce a determinare il numero di livelli numerici disponibili.","astrofotografia.html"],"profondita-ottica":["La profondità ottica misura quanto un mezzo ostacola la propagazione della radiazione lungo un percorso e a una frequenza specificata; è una grandezza senza unità.","lezione-5-4.html"],"protone":["Il protone è una particella composta con carica elettrica positiva pari alla carica elementare; insieme ai neutroni costituisce i nuclei atomici ordinari.","lezione-4-3.html"],"protopianeta":["Un protopianeta è un corpo planetario ancora nelle fasi di formazione e accrescimento.","lezione-3-6.html"],"protostella":["Una protostella è un oggetto in formazione che accumula materia e si riscalda nel processo che può condurre a una stella stabile nella sequenza principale.","lezione-4-5.html"],"protuberanza-solare":["Una protuberanza solare è una struttura di plasma relativamente denso e freddo rispetto alla corona circostante, sostenuta e organizzata dal campo magnetico sopra la superficie del Sole.","lezione-2-3.html"],"pulsar":["Una pulsar è una stella di neutroni dalla quale riceviamo impulsi periodici legati alla rotazione e alla geometria dell’emissione.","lezione-10-3.html"],"punto-equinoziale":["Intersezione fra eclittica ed equatore celeste. Quello di primavera è l’origine convenzionale dell’ascensione retta.","lezione-1-6.html"],"punto-rugiada":["Il punto di rugiada è la temperatura alla quale, raffreddando aria con contenuto di vapore e pressione considerati costanti, si raggiunge la saturazione rispetto all’acqua liquida.","guide.html"],"punto-triplo":["Il punto triplo è una combinazione di temperatura e pressione alla quale tre fasi di una sostanza coesistono in equilibrio.","lezione-3-2.html"],"pupilla-d-uscita":["La pupilla d’uscita è l’immagine dell’apertura del sistema ottico vista attraverso l’oculare. Il suo diametro aiuta a capire come il fascio luminoso entri nell’occhio.","lezione-7-4.html"],"quadratura":["La quadratura è una configurazione in cui le direzioni di un astro e del Sole risultano separate di circa un angolo retto viste dalla Terra, con una convenzione geometrica specificata.","lezione-3-6.html"],"quadrupolo-gravitazionale":["Il quadrupolo gravitazionale descrive una parte della distribuzione spaziale della massa oltre la componente sferica; la sua variazione è centrale nella descrizione introduttiva dell’emissione di onde gravitazionali.","lezione-10-3.html"],"quantita-di-moto":["La quantità di moto è una grandezza vettoriale che, nel regime classico, è il prodotto della massa per la velocità del corpo.","lezione-3-6.html"],"quantizzazione":["In fisica la quantizzazione riguarda la descrizione quantistica e, per determinate grandezze e sistemi, la presenza di valori discreti; il termine ha anche un diverso uso nella conversione digitale.","lezione-4-3.html"],"quanto":["In fisica un quanto è una quantità elementare associata a un processo o a un campo quantizzato. Per la radiazione elettromagnetica il quanto è il fotone.","lezione-4-3.html"],"quark":["I quark sono particelle elementari del Modello standard che partecipano all’interazione forte; protoni e neutroni sono sistemi composti che li contengono.","lezione-6-5.html"],"quasar":["Un quasar è un nucleo galattico attivo molto luminoso, alimentato dall’accrescimento di materia attorno a un buco nero supermassiccio.","lezione-6-2.html"],"radiante-meteorico":["Il radiante meteorico è la direzione celeste dalla quale sembrano divergere le traiettorie delle meteore appartenenti a uno stesso sciame.","lezione-8-2.html"],"radiante-unita":["Il radiante è l’unità SI dell’angolo piano: un angolo di un radiante sottende un arco lungo quanto il raggio della circonferenza.","lezione-1-6.html"],"radiazione":["La radiazione elettromagnetica trasporta energia e comprende onde radio, microonde, infrarosso, luce visibile, ultravioletto, raggi X e gamma.","lezione-4-3.html"],"radiazione-cosmica-fondo":["La radiazione cosmica di fondo a microonde è una radiazione fossile dell’Universo caldo, osservata oggi con spettro quasi di corpo nero a circa 2,7 kelvin.","lezione-6-5.html"],"radicale-chimico":["Nel significato moderno qui adottato, un radicale è una specie chimica con uno o più elettroni spaiati.","lezione-3-6.html"],"radioattivita":["La radioattività è l’insieme dei processi spontanei nei quali nuclei instabili si trasformano emettendo particelle o radiazione. Il singolo processo è chiamato decadimento radioattivo.","lezione-10-4.html"],"radiogalassia":["Una radiogalassia è una galassia con emissione radio particolarmente intensa, spesso associata ad attività del nucleo e a strutture di getti e lobi estese oltre la componente stellare visibile.","lezione-6-2.html"],"radiolobo":["Un radiolobo è una regione estesa di emissione radio associata all’alimentazione e all’evoluzione dei getti di un nucleo galattico attivo.","lezione-6-2.html"],"radiotelescopio":["Un radiotelescopio raccoglie e misura radiazione elettromagnetica nelle bande radio, attraverso antenne, ricevitori e sistemi di elaborazione.","lezione-10-5.html"],"raggi-cosmici":["I raggi cosmici sono particelle energetiche provenienti dallo spazio; il termine comprende nel contesto appropriato anche le particelle secondarie prodotte nelle loro interazioni.","lezione-10-4.html"],"raggi-gamma":["I raggi gamma sono radiazione elettromagnetica di alta energia, studiata in astronomia per conoscere processi energetici e sorgenti compatte.","lezione-10-3.html"],"raggi-x":["I raggi X sono radiazione elettromagnetica con fotoni di energia superiore a quelli del visibile e dell’ultravioletto, usata per studiare molti ambienti astrofisici energetici.","lezione-10-5.html"],"raggio-solare":["Il raggio solare è una scala di lunghezza usata per descrivere il Sole e confrontare le dimensioni delle stelle; il raggio solare nominale IAU vale esattamente 695.700 km.","lezione-4-2.html"],"rame":["Il rame è l’elemento chimico di simbolo Cu e numero atomico 29, un metallo buon conduttore di elettricità e calore, importante anche nei materiali della strumentazione.","strumentazione.html"],"ramo-asintotico-giganti":["Il ramo asintotico delle giganti, AGB, è una fase evolutiva di stelle di massa bassa o intermedia, caratterizzata da grande luminosità, involucro esteso e produzione energetica in gusci attorno a un nucleo evoluto.","lezione-4-6.html"],"rapporto-focale":["Il rapporto focale è la lunghezza focale del sistema divisa per il diametro della sua apertura. Si indica comunemente con scritture come f/5 o f/10.","strumentazione.html"],"rapporto-isotopico":["Un rapporto isotopico confronta le quantità di due isotopi specificati, normalmente attraverso il rapporto fra i rispettivi numeri di atomi.","lezione-3-6.html"],"rapporto-segnale-rumore":["Il rapporto segnale/rumore confronta l’intensità del segnale utile con l’entità delle fluttuazioni che ne limitano la misura, usando una convenzione dichiarata.","astrofotografia.html"],"reazione-acido-base":["Nel modello di Brønsted una reazione acido-base trasferisce un protone da una specie donatrice, l’acido, a una specie accettrice, la base.","lezione-10-2.html"],"reazione-chimica":["Una reazione chimica trasforma specie reagenti in prodotti mediante cambiamenti dei legami e della distribuzione elettronica, senza modificare l’identità dei nuclei come in una reazione nucleare.","lezione-5-4.html"],"redshift":["Lo spostamento verso il rosso indica un aumento della lunghezza d’onda osservata rispetto al valore a riposo della stessa caratteristica spettrale.","lezione-6-5.html"],"regolite":["La regolite è lo strato di materiale sciolto o frammentato che ricopre una superficie rocciosa, con proprietà legate alla storia del corpo e ai processi che lo modificano.","lezione-2-5.html"],"reionizzazione":["La reionizzazione è la trasformazione di gran parte del gas intergalattico, divenuto prevalentemente neutro dopo la ricombinazione, in gas nuovamente ionizzato dall’energia delle prime sorgenti.","lezione-6-5.html"],"relativita-generale":["La relatività generale descrive la gravità attraverso la geometria dello spaziotempo, collegata alla distribuzione di materia, energia e alle loro proprietà fisiche.","lezione-10-3.html"],"relativita-ristretta":["La relatività ristretta è la teoria che collega misure di spazio, tempo e moto nei riferimenti inerziali, assumendo le stesse leggi fisiche e la stessa velocità della luce nel vuoto per tutti questi osservatori.","lezione-10-3.html"],"resistenza-elettrica":["La resistenza elettrica caratterizza il rapporto fra tensione e corrente di un componente nelle condizioni considerate; si misura in ohm.","strumentazione.html"],"resistivita":["La resistività descrive l’opposizione di un materiale al passaggio di corrente elettrica nel modello di conduzione considerato. Nel SI si misura in ohm metro.","strumentazione.html"],"resto-di-supernova":["Un resto di supernova è la struttura in evoluzione prodotta dal materiale espulso e dalla sua interazione con l’ambiente dopo un’esplosione di supernova.","lezione-5-5.html"],"rete-cosmica":["La rete cosmica è la struttura su grande scala della materia, organizzata in filamenti, nodi, pareti e regioni meno dense.","lezione-6-4.html"],"reticolo-di-diffrazione":["Un reticolo di diffrazione è un elemento ottico con una struttura periodica che distribuisce la radiazione in direzioni dipendenti dalla lunghezza d’onda attraverso diffrazione e interferenza.","lezione-4-3.html"],"ricombinazione":["In un gas ionizzato la ricombinazione è la cattura di un elettrone libero da parte di uno ione positivo, che ne riduce la carica positiva; può coinvolgere emissione di radiazione e altri meccanismi.","lezione-5-4.html"],"riconnessione-magnetica":["La riconnessione magnetica è un processo nel quale cambia la connessione del campo magnetico in un plasma e una parte dell’energia magnetica può essere trasferita a particelle e moti.","lezione-2-3.html"],"riduttore-focale":["Un riduttore di focale è un gruppo ottico che diminuisce la focale effettiva di un sistema compatibile, modificando scala e campo dell’immagine.","astrofotografia.html"],"riflessione":["In ottica la riflessione rinvia parte della luce nel mezzo da cui proviene quando incontra una superficie; è il principio usato dagli specchi dei telescopi.","lezione-7-3.html"],"riflettanza":["La riflettanza esprime la frazione della radiazione incidente che una superficie riflette, con condizioni spettrali e geometriche di misura specificate.","lezione-3-2.html"],"riflettore":["Telescopio che usa uno specchio come elemento principale per raccogliere e focalizzare la luce.","lezione-7-3.html"],"rifrattore":["Telescopio il cui obiettivo principale è costituito da lenti.","lezione-7-3.html"],"rifrazione":["La rifrazione modifica la propagazione della luce attraverso mezzi con proprietà ottiche differenti e contribuisce sia al funzionamento delle lenti sia alla vista atmosferica degli astri.","lezione-8-4.html"],"riga-21cm":["La linea a circa 21 centimetri è una transizione iperfine dell’idrogeno atomico neutro, con frequenza a riposo di circa 1420 megahertz.","lezione-6-1.html"],"riga-assorbimento":["Una riga di assorbimento è una diminuzione dell’intensità in un intervallo ristretto dello spettro rispetto alla radiazione circostante, prodotta dall’interazione della luce con la materia.","lezione-4-3.html"],"riga-proibita":["Una riga proibita è associata a una transizione radiativa molto poco probabile nel meccanismo dominante di dipolo elettrico, ma possibile attraverso altri contributi.","lezione-5-4.html"],"riga-spettrale":["Una riga spettrale è una struttura di emissione o assorbimento concentrata attorno a una frequenza o lunghezza d’onda, la cui posizione e forma possono rivelare proprietà della sorgente.","lezione-4-3.html"],"ripetibilita":["La ripetibilità descrive la precisione ottenuta ripetendo misure in condizioni specificate mantenute sostanzialmente uguali, come metodo, sistema di misura e breve intervallo temporale.","lezione-9-4.html"],"risoluzione-angolare":["La risoluzione angolare descrive la capacità di distinguere dettagli o sorgenti vicine per direzione, secondo un criterio e condizioni di misura dichiarati.","strumentazione.html"],"risoluzione-spettrale":["La risoluzione spettrale indica quanto vicine in lunghezza d’onda o frequenza possano essere due caratteristiche ancora distinguibili in uno spettro.","lezione-4-3.html"],"risonanza-orbitale":["Una risonanza orbitale è una relazione dinamica fra frequenze o periodi del moto che può rendere ricorrenti e importanti determinate perturbazioni gravitazionali.","lezione-3-6.html"],"risonanza-spin-orbita":["Una risonanza spin–orbita lega il periodo di rotazione di un corpo al suo periodo orbitale attraverso un rapporto caratteristico.","lezione-3-6.html"],"ritorno-campioni":["Il ritorno di campioni è una modalità di esplorazione che preleva materiale extraterrestre e lo porta sulla Terra per analisi in laboratorio.","lezione-10-5.html"],"rivoluzione":["La rivoluzione è il moto orbitale di un corpo rispetto a un altro o al comune centro di massa; è distinta dalla rotazione attorno al proprio asse.","lezione-2-1.html"],"rosetta":["Rosetta fu la missione ESA che raggiunse la cometa 67P/Churyumov–Gerasimenko nel 2014, accompagnandola lungo l’orbita e trasportando il lander Philae.","lezione-3-5.html"],"rotazione":["La rotazione descrive un cambiamento di orientamento attorno a un asse; in astronomia va distinta dalla rivoluzione orbitale.","lezione-2-1.html"],"rotazione-campo":["La rotazione del campo è il cambiamento dell’orientamento del cielo nell’immagine durante l’inseguimento, anche quando il bersaglio centrale rimane puntato.","strumentazione.html"],"rotazione-sincrona":["La rotazione sincrona è una risonanza nella quale il periodo di rotazione di un corpo coincide con quello della sua rivoluzione orbitale, nel riferimento appropriato.","lezione-2-4.html"],"rover":["Un rover è un veicolo capace di spostarsi sulla superficie di un corpo celeste per esplorare luoghi diversi e trasportare strumenti o persone.","lezione-10-5.html"],"rubin-vera":["Vera Rubin (1928–2016) fu un’astronoma statunitense le cui misure della rotazione delle galassie, anche in collaborazione con Kent Ford, rafforzarono le evidenze di materia non visibile.","lezione-6-4.html"],"rumore-di-lettura":["Il rumore di lettura è la fluttuazione introdotta dalla catena elettronica durante la lettura e la conversione del segnale del rivelatore.","astrofotografia.html"],"rumore-fotonico":["Il rumore fotonico è la fluttuazione statistica associata al numero di fotoni rilevati in un intervallo, anche quando il flusso medio della sorgente rimane stabile.","astrofotografia.html"],"rutherford-ernest":["Ernest Rutherford (1871–1937) fu un fisico protagonista dello studio della radioattività e della struttura nucleare dell’atomo, interpretata attraverso esperimenti di diffusione di particelle.","lezione-4-3.html"],"satellite-artificiale":["Un satellite artificiale è un oggetto costruito e immesso in orbita dall’uomo; nel significato orbitale qui usato segue il moto attorno a un corpo celeste.","lezione-8-1.html"],"satellite-naturale":["Un satellite naturale è un corpo formatosi attraverso processi naturali che orbita attorno a un altro corpo non stellare, come un pianeta o un piccolo corpo del Sistema solare.","lezione-3-4.html"],"saturazione":["Nella ripresa astronomica la saturazione indica il raggiungimento di un limite della risposta del rivelatore o della catena di lettura, oltre il quale l’informazione non cresce normalmente con il segnale incidente.","astrofotografia.html"],"saturno":["Saturno è un pianeta gigante del Sistema solare, noto per gli anelli estesi composti da moltissime particelle e per il suo ricco sistema di satelliti.","lezione-3-3.html"],"scala-bortle":["La scala Bortle classifica qualitativamente l’aspetto osservativo del cielo notturno in nove classi, dalla 1 più buia alla 9 fortemente illuminata.","lezione-7-5.html"],"scala-immagine":["La scala dell’immagine collega una distanza sul rivelatore o sulla rappresentazione a una separazione angolare nel cielo, spesso espressa in secondi d’arco per pixel.","astrofotografia.html"],"schiaparelli-giovanni":["Giovanni Virginio Schiaparelli (1835–1910) fu un astronomo italiano, direttore dell’Osservatorio di Brera, noto per gli studi di Marte e per il collegamento fra sciami meteorici e comete.","lezione-3-2.html"],"schmidt-cassegrain":["Lo Schmidt–Cassegrain è un telescopio catadiottrico che combina una lastra correttrice con specchio primario e secondario, ripiegando il percorso della luce in un tubo compatto.","strumentazione.html"],"sciame-meteorico":["Uno sciame meteorico è un aumento di meteore associate a una popolazione di particelle con orbite correlate, che la Terra incontra lungo il proprio percorso.","lezione-8-2.html"],"scintillazione":["La scintillazione astronomica è la rapida variazione apparente della luce di una sorgente, prodotta dalla propagazione attraverso un mezzo irregolare. Nelle stelle osservate da terra dipende soprattutto dall’atmosfera.","lezione-7-5.html"],"scudo-termico":["Uno scudo termico è una protezione progettata per limitare il riscaldamento delle parti di un veicolo durante condizioni intense, come un ingresso atmosferico.","lezione-10-5.html"],"secchi-angelo":["Angelo Secchi (1818–1878) fu un astronomo italiano, gesuita, tra i protagonisti della spettroscopia stellare e dello studio fisico del Sole nell’Ottocento.","lezione-4-3.html"],"secondo-d-arco":["Il secondo d’arco è un’unità angolare pari a un sessantesimo di primo d’arco, cioè a un tremilaseicentesimo di grado; si indica con ″.","lezione-6-3.html"],"secondo-tempo":["Il secondo, simbolo s, è l’unità SI del tempo, definita mediante la frequenza di una transizione dell’atomo di cesio-133 in condizioni specificate.","lezione-9-3.html"],"sedimentazione":["La sedimentazione è l’accumulo di materiale trasportato o formato in un ambiente, che costruisce depositi interpretabili attraverso composizione, strutture e relazioni con il paesaggio.","lezione-3-2.html"],"seeing":["La turbolenza atmosferica altera e allarga l’immagine degli astri: il seeing descrive questo effetto sulla qualità osservativa.","lezione-7-5.html"],"segnale":["Un segnale è una grandezza fisica o una variazione che trasporta informazione; nella misura astronomica si distingue il contributo d’interesse dai fondi e dalle fluttuazioni.","astrofotografia.html"],"semiasse-maggiore":["Il semiasse maggiore di un’ellisse è metà del suo asse più lungo; nelle orbite ellittiche è una misura fondamentale della dimensione dell’orbita.","lezione-3-6.html"],"semimetallo-chimico":["Nella classificazione chimica introduttiva, semimetallo o metalloide indica elementi con proprietà intermedie fra quelle tipiche dei metalli e dei non metalli.","lezione-10-2.html"],"sensore":["Un sensore fotografico converte una parte della radiazione ricevuta in un segnale misurabile, con una risposta e limiti propri.","astrofotografia.html"],"sequenza-principale":["La sequenza principale è la regione del diagramma di Hertzsprung–Russell occupata dalle stelle che sostengono la propria produzione energetica soprattutto con la fusione dell’idrogeno nel centro.","lezione-4-4.html"],"serie-balmer":["La serie di Balmer comprende transizioni dell’idrogeno atomico fra il livello con numero principale due e livelli superiori; le prime righe cadono nel visibile.","lezione-4-3.html"],"serie-lyman":["La serie di Lyman comprende transizioni dell’idrogeno atomico fra il livello fondamentale e livelli superiori; le lunghezze d’onda di riposo appartengono all’ultravioletto.","lezione-4-3.html"],"sezione-urto":["La sezione d’urto è una grandezza con dimensioni di area che esprime quanto sia probabile un determinato processo di interazione nelle condizioni considerate.","lezione-10-4.html"],"sfera-celeste":["Superficie immaginaria sulla quale rappresentiamo le direzioni degli astri, senza collocarli tutti alla stessa distanza reale.","lezione-1-1.html"],"significativita-statistica":["La significatività statistica riguarda la compatibilità dei dati con un’ipotesi di riferimento secondo un metodo e una soglia dichiarati.","lezione-9-4.html"],"silicato":["I silicati sono composti nei quali silicio e ossigeno formano unità strutturali combinate con altri elementi. Costituiscono una parte fondamentale delle rocce e delle polveri cosmiche.","lezione-3-2.html"],"silicio":["Il silicio è l’elemento di numero atomico 14 e simbolo Si, importante nei silicati dei mondi rocciosi e nei semiconduttori.","lezione-3-2.html"],"sistema-solare":["Il Sistema solare comprende il Sole e i corpi e materiali legati al suo ambiente gravitazionale, non soltanto gli otto pianeti.","lezione-3-1.html"],"smart-telescope":["Uno smart telescope integra ottica, rivelatore, movimento e software per automatizzare una parte dell’osservazione e della produzione di immagini.","strumentazione.html"],"sodio":["Il sodio è l’elemento di numero atomico 11, simbolo Na. Le sue righe gialle hanno applicazioni sia nella spettroscopia sia nella creazione di stelle guida artificiali.","lezione-7-3.html"],"soho":["SOHO, Solar and Heliospheric Observatory, è una missione congiunta ESA e NASA dedicata alla struttura del Sole, alla corona e al vento solare.","lezione-2-3.html"],"solar-orbiter":["Solar Orbiter è una missione ESA con partecipazione NASA che combina osservazioni del Sole e misure del plasma e dei campi nell’ambiente attraversato dalla sonda.","lezione-2-3.html"],"sole":["Il Sole è la stella del nostro Sistema solare: la sua radiazione, gravità e attività determinano gran parte dell’ambiente dei pianeti.","lezione-2-3.html"],"solido-amorfo":["Un solido amorfo non presenta l’ordine strutturale a lungo raggio caratteristico di un cristallo.","lezione-3-5.html"],"solstizio":["Un solstizio è l’istante in cui il Sole raggiunge uno degli estremi annuali della sua declinazione, verso nord o verso sud dell’equatore celeste.","lezione-2-2.html"],"solubilita":["La solubilità descrive quanto una sostanza possa essere presente in soluzione all’equilibrio con un’altra fase, nelle condizioni specificate.","lezione-10-2.html"],"soluzione-chimica":["Una soluzione è una miscela omogenea su scala appropriata, nella quale uno o più componenti sono dispersi nel solvente a livello molecolare o ionico.","lezione-10-2.html"],"solvatazione":["La solvatazione è l’interazione delle specie disciolte con le molecole del solvente, che ne modifica ambiente e comportamento.","lezione-10-2.html"],"somma-immagini":["La combinazione di immagini registrate, spesso chiamata stacking, unisce più esposizioni per stimare meglio il segnale e limitare alcuni disturbi, secondo il metodo adottato.","astrofotografia.html"],"sorgente-estesa":["Una sorgente estesa ha una distribuzione spaziale che non può essere trascurata nella misura o nell’osservazione considerata.","lezione-5-1.html"],"sorgente-puntiforme":["Una sorgente puntiforme è trattata come priva di estensione rilevante rispetto alla scala e alla risoluzione del problema considerato.","lezione-7-3.html"],"spallazione":["La spallazione è un processo nucleare nel quale una collisione energetica provoca l’espulsione di più costituenti da un nucleo; contribuisce alla formazione di alcuni elementi leggeri.","lezione-4-6.html"],"spaziotempo":["Lo spaziotempo è la struttura nella quale un evento viene individuato specificando dove e quando avviene. Nella relatività, coordinate spaziali e temporali sono collegate fra loro.","lezione-10-3.html"],"spettro":["Distribuzione della radiazione nelle sue componenti, per esempio secondo la lunghezza d’onda.","lezione-4-3.html"],"spettro-continuo":["Uno spettro continuo presenta radiazione distribuita su un intervallo di frequenze o lunghezze d’onda senza essere costituito soltanto da righe isolate.","lezione-4-3.html"],"spettrografo":["Uno spettrografo separa e registra la radiazione secondo la lunghezza d’onda, permettendo di analizzare lo spettro di una sorgente.","lezione-4-3.html"],"spettrografo-echelle":["Uno spettrografo echelle utilizza un reticolo in ordini elevati, spesso con dispersione incrociata, per ottenere spettri ad alta risoluzione su un ampio intervallo.","lezione-4-3.html"],"spettrometria":["La spettrometria è la misura quantitativa di uno spettro. Nell’osservazione astronomica misura il segnale in funzione della lunghezza d’onda o della frequenza; la spettroscopia comprende anche l’interpretazione fisica delle caratteristiche osservate.","lezione-4-3.html"],"spettrometro":["Uno spettrometro misura come un segnale è distribuito nelle sue componenti spettrali. Nel contesto astronomico si tratta soprattutto della radiazione elettromagnetica: la misura collega intensità e lunghezza d’onda o frequenza.","lezione-4-3.html"],"spettropolarimetria":["La spettropolarimetria misura la polarizzazione in funzione della lunghezza d’onda, collegando informazione spettrale e stato della radiazione.","lezione-4-3.html"],"spettroscopia":["La spettroscopia studia la distribuzione della radiazione nelle sue componenti spettrali e interpreta le firme prodotte dall’emissione, dall’assorbimento e dalla propagazione.","lezione-4-3.html"],"spettroscopio":["Uno spettroscopio separa la luce nelle sue componenti e permette di osservarne lo spettro. Nella forma visuale un prisma o un reticolo disperde la luce, che viene osservata attraverso un sistema ottico.","lezione-4-3.html"],"spianatore-di-campo":["Uno spianatore di campo è un correttore ottico progettato per ridurre la curvatura della superficie di miglior fuoco e adattarla più efficacemente a un rivelatore piano.","astrofotografia.html"],"spicola-solare":["Una spicola solare è una sottile struttura dinamica di plasma osservata nella cromosfera, particolarmente evidente presso il bordo del Sole.","lezione-2-3.html"],"spin":["Lo spin è un momento angolare intrinseco delle particelle: una proprietà quantistica che non coincide con la rotazione di una piccola sfera materiale.","lezione-4-3.html"],"spitzer":["Spitzer fu un telescopio spaziale della NASA dedicato all’infrarosso, operativo scientificamente dal 2003 al 2020.","lezione-10-5.html"],"sputnik-1":["Sputnik 1 fu il primo satellite artificiale posto in orbita terrestre, lanciato dall’Unione Sovietica il 4 ottobre 1957.","lezione-10-5.html"],"starburst":["Uno starburst è una fase di formazione stellare particolarmente intensa rispetto alle caratteristiche e alla storia della galassia o della regione considerata.","lezione-6-2.html"],"stardust":["Stardust è una missione NASA che raccolse particelle della cometa Wild 2 durante un incontro nel 2004 e riportò la capsula con i campioni sulla Terra nel 2006.","lezione-10-5.html"],"stechiometria":["La stechiometria studia i rapporti quantitativi fra le specie che partecipano a una reazione chimica o costituiscono un composto.","lezione-3-6.html"],"stella":["Oggetto astrofisico che, durante parte della propria evoluzione, produce energia attraverso la fusione nucleare.","lezione-4-1.html"],"stella-di-neutroni":["Una stella di neutroni è un residuo stellare estremamente compatto, nel quale la materia raggiunge densità enormi e la componente neutronica ha un ruolo fondamentale.","lezione-10-3.html"],"stella-variabile":["Una stella variabile presenta cambiamenti misurabili della luminosità apparente nel tempo, dovuti a processi fisici della sorgente o alla geometria del sistema.","lezione-4-6.html"],"steradiante":["Lo steradiante, simbolo sr, è l’unità SI dell’angolo solido, che misura l’estensione di un insieme di direzioni nello spazio.","lezione-1-6.html"],"stratosfera":["La stratosfera è lo strato atmosferico sopra la troposfera, nel quale il profilo termico terrestre presenta generalmente un aumento della temperatura con la quota.","lezione-7-5.html"],"stretching":["Lo stretching è una trasformazione dei livelli di un’immagine che rende più visibili differenze di luminosità poco percepibili nella rappresentazione iniziale.","astrofotografia.html"],"stronzio":["Lo stronzio è l’elemento chimico di simbolo Sr e numero atomico 38, appartenente ai metalli alcalino-terrosi. In astronomia è importante anche come indizio di nucleosintesi neutronica.","lezione-10-4.html"],"subgigante":["Una subgigante è una stella classificata fra la sequenza principale e le giganti in luminosità; la fase è collegata all’evoluzione oltre la fusione centrale dell’idrogeno per stelle appropriate.","lezione-4-4.html"],"sublimazione":["La sublimazione è il passaggio diretto di una sostanza dalla fase solida a quella gassosa, senza attraversare una fase liquida intermedia.","lezione-3-5.html"],"super-terra":["Super-Terra è un termine usato per esopianeti più massicci della Terra ma meno massicci dei grandi pianeti giganti; non implica somiglianza ambientale o abitabilità.","lezione-10-1.html"],"superammasso":["Un superammasso è una grande associazione di gruppi e ammassi di galassie, identificata attraverso la struttura e le proprietà della distribuzione su larga scala.","lezione-6-4.html"],"superconduttivita":["La superconduttività è uno stato di alcuni materiali caratterizzato da resistenza elettrica continua nulla e da proprietà magnetiche specifiche entro condizioni critiche.","lezione-10-2.html"],"supergigante":["Una supergigante è una stella appartenente a una classe di luminosità molto elevata; esistono supergiganti con temperature e colori differenti.","lezione-4-4.html"],"supernova":["Una supernova è un evento esplosivo stellare; esistono meccanismi differenti e non è il destino ordinario di ogni stella.","lezione-10-4.html"],"supernova-ia":["Una supernova di tipo Ia è un’esplosione termonucleare associata a una nana bianca in un sistema stellare, riconosciuta attraverso proprietà spettrali e temporali.","lezione-6-3.html"],"swift":["Il Neil Gehrels Swift Observatory è una missione spaziale lanciata nel 2004 per osservare fenomeni transitori in più bande, in particolare lampi gamma.","lezione-10-5.html"],"tachocline":["La tachocline è una regione di transizione nella rotazione interna del Sole, vicina alla base della zona convettiva, importante nei modelli della dinamica magnetica solare.","lezione-2-3.html"],"tavola-periodica":["La tavola periodica organizza gli elementi secondo il numero atomico e mette in evidenza ricorrenze nelle proprietà legate alla struttura elettronica.","lezione-4-3.html"],"telemetria-spaziale":["La telemetria spaziale è la trasmissione a distanza di dati misurati da un veicolo spaziale, relativi agli esperimenti o al suo funzionamento.","lezione-10-5.html"],"telerilevamento":["Il telerilevamento ricava informazioni su oggetti o ambienti a distanza attraverso la misura di radiazione, senza campionare direttamente il materiale studiato.","lezione-10-5.html"],"telescopio":["Strumento che raccoglie radiazione da sorgenti lontane per formarne immagini o misurarne proprietà.","lezione-7-3.html"],"telescopio-spaziale":["Un telescopio spaziale è un osservatorio astronomico collocato nello spazio, progettato per raccogliere radiazione in bande e condizioni determinate dalla missione.","lezione-10-5.html"],"temperatura":["La temperatura descrive uno stato termico e il verso degli scambi spontanei di calore; in astronomia occorre precisare quale regione o quale temperatura equivalente si intende.","lezione-4-3.html"],"temperatura-colore":["La temperatura di colore confronta il colore di una sorgente con quello di un corpo nero; non coincide necessariamente con la temperatura fisica del materiale emittente.","astrofotografia.html"],"temperatura-efficace":["La temperatura efficace di una stella è la temperatura di un corpo nero che emetterebbe la stessa potenza totale per unità di superficie.","lezione-4-2.html"],"tempo-dimezzamento":["Il tempo di dimezzamento è l’intervallo nel quale, nel modello di decadimento considerato, rimane mediamente metà dei nuclei iniziali del nuclide radioattivo.","lezione-10-4.html"],"tempo-integrazione":["Il tempo di integrazione descrive l’intervallo complessivo di raccolta del segnale considerato in una misura, che può comprendere una o più esposizioni utilizzate.","astrofotografia.html"],"tempo-lookback":["Il tempo di lookback è l’intervallo fra l’emissione della luce osservata da una sorgente e la sua ricezione, espresso nel quadro cosmologico adottato.","lezione-6-3.html"],"tempo-siderale":["Il tempo siderale esprime l’orientamento della rotazione terrestre rispetto al riferimento equinoziale. Localmente indica l’ascensione retta che sta transitando al meridiano superiore, con convenzioni coerenti.","lezione-1-6.html"],"tempo-universale":["Il Tempo Universale è una famiglia di riferimenti temporali legati alla rotazione terrestre. UT1 descrive l’angolo di rotazione della Terra e va distinto da UTC.","lezione-9-3.html"],"terminatore":["Il terminatore separa la regione illuminata da quella in ombra su un corpo: la sua forma apparente dipende dalla geometria e dal rilievo.","lezione-2-5.html"],"terra":["La Terra è il terzo pianeta dal Sole e il punto di osservazione da cui descriviamo il cielo locale.","lezione-2-1.html"],"tesla-unita":["Il tesla, simbolo T, è l’unità SI dell’induzione magnetica B, comunemente chiamata campo magnetico nel contesto appropriato.","lezione-2-3.html"],"tess":["TESS è il Transiting Exoplanet Survey Satellite della NASA, lanciato nel 2018 per cercare esopianeti attraverso transiti osservati in ampie regioni del cielo.","lezione-10-1.html"],"testa-a-sfera":["Una testa a sfera è un supporto orientabile fra treppiede o altro sostegno e apparecchiatura, che permette di impostare e bloccare una direzione entro i limiti meccanici previsti.","strumentazione.html"],"tettonica-placche":["La tettonica delle placche è il quadro che descrive la dinamica della litosfera terrestre suddivisa in placche mobili e le interazioni ai loro margini.","lezione-3-2.html"],"tilt-sensore":["Il tilt del sensore è un’inclinazione indesiderata del piano sensibile rispetto al piano immagine previsto, capace di produrre differenze di fuoco attraverso il campo.","astrofotografia.html"],"titanio":["Il titanio è l’elemento di numero atomico 22, simbolo Ti. I suoi isotopi e composti compaiono nello studio dei materiali planetari e dei prodotti delle esplosioni stellari.","lezione-10-4.html"],"titano-satellite":["Titano è il maggiore satellite di Saturno, dotato di una densa atmosfera e di laghi e mari superficiali di idrocarburi liquidi.","lezione-3-4.html"],"tolomeo-claudio":["Claudio Tolomeo fu uno studioso attivo ad Alessandria nel II secolo d.C., autore dell’Almagesto e di un’importante sistemazione matematica dell’astronomia geocentrica.","lezione-1-3.html"],"transiente-astronomico":["Un transiente astronomico è un fenomeno che compare o cambia sensibilmente su una scala temporale rilevante per l’osservazione, rispetto al comportamento abituale della sorgente.","lezione-9-4.html"],"transito":["Un transito può indicare il passaggio apparente di un corpo davanti al disco di un altro; nel contesto delle effemeridi può anche riferirsi al passaggio al meridiano.","lezione-10-1.html"],"transizione-fase":["Una transizione di fase è un cambiamento dello stato o dell’organizzazione fisica della materia al variare delle condizioni.","lezione-3-3.html"],"transizione-rotazionale":["Una transizione rotazionale è un cambiamento fra stati energetici associati alla rotazione quantizzata di una molecola. Può contribuire a righe osservate soprattutto nel radio e nell’infrarosso lontano.","lezione-4-3.html"],"transizione-vibrazionale":["Una transizione vibrazionale è un cambiamento fra stati energetici associati ai moti di vibrazione degli atomi di una molecola. Molte di queste transizioni contribuiscono allo spettro infrarosso.","lezione-4-3.html"],"transnettuniano":["Un oggetto transnettuniano è un corpo del Sistema solare con orbita caratterizzata da semiasse maggiore oltre quello di Nettuno; la categoria comprende popolazioni dinamiche differenti.","lezione-3-5.html"],"trasparenza-atmosferica":["La trasparenza atmosferica descrive quanto efficacemente la radiazione attraversi l’atmosfera nella banda considerata. Assorbimento e diffusione possono ridurre il segnale proveniente dagli astri.","lezione-7-5.html"],"trasporto-radiativo":["Il trasporto radiativo descrive come la radiazione si propaga e cambia attraverso emissione, assorbimento e diffusione nell’interazione con la materia.","lezione-4-1.html"],"trattamento-antiriflesso":["Un trattamento antiriflesso riduce la riflessione di una superficie ottica in determinate condizioni di lunghezza d’onda e angolo d’incidenza.","strumentazione.html"],"treppiede":["Il treppiede è un supporto a tre gambe che sostiene strumenti, montature o teste fotografiche. La sua stabilità condiziona la qualità dell’osservazione e della ripresa.","lezione-7-6.html"],"triplo-alfa":["Il processo triplo alfa costruisce carbonio-12 a partire da tre nuclei di elio-4, attraverso passaggi nucleari favoriti nelle condizioni del bruciamento dell’elio stellare.","lezione-4-6.html"],"tritone":["Tritone è il maggiore satellite di Nettuno e percorre un’orbita retrograda rispetto alla rotazione del pianeta.","lezione-3-4.html"],"trizio":["Il trizio è l’isotopo radioattivo dell’idrogeno con un protone e due neutroni nel nucleo; si indica con ³H o T.","lezione-4-1.html"],"tropico":["I tropici terrestri sono i paralleli che delimitano le latitudini alle quali il centro del Sole può raggiungere lo zenit nel corso dell’anno, nel modello geometrico usuale.","lezione-2-2.html"],"troposfera":["La troposfera è lo strato più basso dell’atmosfera terrestre, caratterizzato in media da temperatura decrescente con la quota e sede della maggior parte dei fenomeni meteorologici.","lezione-7-5.html"],"turbolenza-atmosferica":["La turbolenza atmosferica è un moto irregolare dell’aria; le variazioni delle proprietà ottiche lungo il percorso della luce possono degradare l’immagine astronomica.","guide.html"],"ultravioletto":["La radiazione ultravioletta ha lunghezze d’onda più corte del violetto visibile e non viene percepita direttamente come un colore dall’occhio.","lezione-4-3.html"],"umidita-relativa":["L’umidità relativa confronta la pressione del vapore acqueo presente con quella di saturazione alla stessa temperatura, normalmente esprimendo il rapporto in percentuale.","guide.html"],"unita-astronomica":["L’unità astronomica è una lunghezza convenzionale esatta di 149.597.870.700 metri, usata soprattutto per le distanze nel Sistema solare.","lezione-6-3.html"],"unita-massa-atomica":["L’unità di massa atomica unificata, simbolo u, è un dodicesimo della massa di un atomo libero di carbonio-12, a riposo e nel suo stato fondamentale; è detta anche dalton, Da.","lezione-4-3.html"],"universo":["In cosmologia l’Universo comprende spazio, tempo, materia, radiazione e le strutture fisiche che studiamo; l’Universo osservabile non coincide necessariamente con il tutto.","lezione-6-5.html"],"universo-osservabile":["L’Universo osservabile è la regione dalla quale segnali hanno potuto raggiungerci nel tempo cosmico disponibile. Il suo limite non coincide con un bordo materiale dell’intero Universo.","lezione-6-5.html"],"uranio":["L’uranio è l’elemento chimico di simbolo U e numero atomico 92. I suoi isotopi sono radioattivi e alcuni sono importanti per datazione e fisica nucleare.","lezione-10-4.html"],"urano":["Urano è il settimo pianeta dal Sole, un gigante di ghiaccio con asse di rotazione fortemente inclinato rispetto al piano orbitale.","lezione-3-3.html"],"utc":["UTC, Tempo Universale Coordinato, è la scala temporale internazionale prodotta dal BIPM attraverso il confronto di realizzazioni basate su orologi atomici.","lezione-9-3.html"],"valenza":["La valenza esprime la capacità di combinazione di un atomo, tradizionalmente riferita al numero di legami che può formare in un determinato composto.","lezione-10-2.html"],"velocita-angolare":["La velocità angolare descrive quanto rapidamente varia un angolo nel tempo, rispetto a un asse o a un riferimento dichiarato.","lezione-1-3.html"],"velocita-della-luce":["Nel vuoto la velocità della luce, indicata con c, vale esattamente 299.792.458 metri al secondo nel Sistema Internazionale.","lezione-4-3.html"],"velocita-di-fuga":["La velocità di fuga è la velocità minima iniziale che, nel modello gravitazionale considerato e senza ulteriore propulsione, permette a un corpo di allontanarsi senza ricadere.","lezione-3-6.html"],"velocita-orbitale":["La velocità orbitale descrive il moto di un corpo lungo l’orbita, con valore e direzione riferiti a un sistema specificato.","lezione-3-6.html"],"velocita-radiale":["La velocità radiale è la componente del moto relativo lungo la linea di vista, distinta dal movimento trasversale sul piano del cielo.","lezione-4-1.html"],"velocita-suono":["La velocità del suono è la rapidità con cui una piccola perturbazione meccanica di pressione si propaga in un mezzo nelle condizioni considerate.","lezione-4-1.html"],"velocita-vettoriale":["La velocità vettoriale descrive la variazione della posizione nel tempo, includendo rapidità, direzione e verso del moto rispetto a un riferimento.","lezione-3-6.html"],"venera-7":["Venera 7 fu una missione sovietica che nel dicembre 1970 trasmise dati dalla superficie di Venere, una tappa fondamentale dell’esplorazione planetaria.","lezione-10-5.html"],"venera-9":["Venera 9 fu una missione sovietica del 1975, con un orbiter e un modulo di discesa che trasmise immagini dalla superficie di Venere.","lezione-3-2.html"],"venere":["Venere è il secondo pianeta dal Sole, un mondo roccioso avvolto da una densa atmosfera e da nubi che nascondono il terreno alla vista ordinaria.","lezione-3-2.html"],"vento-solare":["Il vento solare è un flusso di plasma proveniente dall’atmosfera esterna del Sole e diffuso nello spazio interplanetario.","lezione-8-3.html"],"vento-stellare":["Un vento stellare è un flusso di materia che si allontana da una stella, contribuendo alla perdita di massa e all’interazione con l’ambiente circostante.","lezione-4-6.html"],"versore":["Un versore è un vettore di modulo unitario usato per indicare una direzione e un verso.","lezione-1-6.html"],"verticale-locale":["La verticale locale è la direzione definita dalla gravità effettiva nel luogo. Un filo a piombo in equilibrio ne fornisce un riferimento pratico.","lezione-1-6.html"],"vettore":["Un vettore descrive una grandezza con intensità, direzione e verso, e segue regole di composizione che tengono conto dell’orientamento.","lezione-3-6.html"],"via-lattea":["La Via Lattea è la galassia a cui appartiene il Sole; la fascia chiara nel cielo è una vista interna della sua struttura stellare e diffusa.","lezione-6-1.html"],"vignettatura":["Nella ripresa fotografica la vignettatura è una diminuzione dell’illuminazione verso i bordi del campo, dovuta alla geometria e alla trasmissione del sistema.","astrofotografia.html"],"viking-1":["Viking 1 fu una missione NASA composta da orbiter e lander; il lander operò sulla superficie marziana dopo l’atterraggio del 20 luglio 1976.","lezione-10-5.html"],"viriale-teorema":["Il teorema del viriale collega medie del moto e delle forze di un sistema; in condizioni appropriate permette di collegare energia cinetica e potenziale gravitazionale.","lezione-6-4.html"],"visione-distolta":["La visione distolta è una tecnica visuale che consiste nel guardare leggermente accanto a un oggetto debole per favorirne la percezione con regioni retiniche adatte alla luce tenue.","lezione-7-1.html"],"vita-media":["Nel decadimento esponenziale la vita media è il tempo medio prima della trasformazione di una particella o di un nucleo; è distinta dal tempo di dimezzamento.","lezione-4-6.html"],"volt":["Il volt, simbolo V, è l’unità SI della differenza di potenziale elettrico: un volt equivale a un joule per coulomb.","strumentazione.html"],"voyager-1":["Voyager 1 è la sonda NASA lanciata il 5 settembre 1977, protagonista dei sorvoli di Giove e Saturno e dell’ingresso nello spazio interstellare oltre l’eliopausa nel 2012.","lezione-10-5.html"],"voyager-2":["Voyager 2 è una sonda NASA lanciata nel 1977 che ha sorvolato Giove, Saturno, Urano e Nettuno e ha proseguito verso lo spazio interstellare.","lezione-10-5.html"],"vulcanismo":["Il vulcanismo comprende processi attraverso i quali magma e gas provenienti dall’interno di un corpo raggiungono o influenzano la sua superficie.","lezione-3-2.html"],"vuoto-cosmico":["Un vuoto cosmico è una grande regione con densità di materia e galassie inferiore alla media, non necessariamente completamente priva di contenuto.","lezione-6-4.html"],"watt":["Il watt, simbolo W, è l’unità SI della potenza e corrisponde al trasferimento o alla trasformazione di un joule di energia in un secondo.","lezione-4-2.html"],"wcs":["Il World Coordinate System descrive la corrispondenza fra coordinate dei pixel e coordinate fisiche, come le direzioni celesti, attraverso metadati e trasformazioni definite.","lezione-9-4.html"],"white-balance":["Il bilanciamento del bianco regola il rapporto fra i canali cromatici per interpretare i colori rispetto a un riferimento. In fotografia astronomica non sostituisce la calibrazione scientifica del colore.","astrofotografia.html"],"wien-legge":["La legge dello spostamento di Wien collega la temperatura di un corpo nero alla lunghezza d’onda del massimo della sua distribuzione spettrale espressa per unità di lunghezza d’onda.","lezione-4-3.html"],"wimp":["WIMP indica una famiglia ipotetica di particelle massive debolmente interagenti, studiata fra i possibili costituenti della materia oscura.","lezione-6-5.html"],"wolf-rayet":["Le stelle di Wolf–Rayet sono riconosciute da caratteristiche spettrali di emissione intense e larghe, associate a venti stellari densi e a condizioni atmosferiche estreme.","lezione-4-6.html"],"x-binarie":["Le binarie X sono sistemi doppi nei quali il trasferimento e l’accrescimento di materia su un oggetto compatto producono un’importante emissione nei raggi X.","lezione-10-3.html"],"xeno":["Lo xeno, o xenon, è l’elemento chimico di simbolo Xe e numero atomico 54, appartenente al gruppo dei gas nobili.","lezione-10-5.html"],"xmm-newton":["XMM-Newton è un osservatorio spaziale dell’ESA dedicato soprattutto allo studio delle sorgenti di raggi X, con strumenti complementari in altre bande.","lezione-10-5.html"],"y-nane":["Le nane di classe Y sono oggetti substellari molto freddi, classificati attraverso le caratteristiche del loro spettro. Sono studiate soprattutto nell’infrarosso.","lezione-4-4.html"],"yarkovsky":["L’effetto Yarkovsky è una piccola variazione del moto orbitale di un corpo, come un asteroide, dovuta alla riemissione termica non simmetrica dell’energia assorbita dal Sole.","lezione-3-5.html"],"yorp":["L’effetto YORP descrive una variazione della rotazione di un piccolo corpo dovuta al momento torcente prodotto dalla radiazione riflessa ed emessa dalla sua superficie.","lezione-3-5.html"],"yso":["YSO è la sigla inglese di Young Stellar Object, oggetto stellare giovane. Raggruppa sorgenti nelle prime fasi della formazione e dell’evoluzione stellare.","lezione-4-5.html"],"zenit":["Direzione della verticale locale rivolta verso l’alto, sulla sfera celeste.","lezione-1-1.html"],"zero-assoluto":["Lo zero assoluto è lo zero della temperatura termodinamica: 0 kelvin, corrispondenti a −273,15 gradi Celsius.","lezione-4-3.html"],"zero-fotometrico":["Lo zero fotometrico è il riferimento di calibrazione che collega un segnale misurato alla scala delle magnitudini in un determinato sistema e banda.","lezione-4-2.html"],"zhr":["Lo ZHR è un tasso meteorico normalizzato alle condizioni di riferimento: radiante allo zenit, magnitudine limite visuale 6,5 e cielo libero nelle condizioni previste dal metodo.","lezione-8-2.html"],"zinco":["Lo zinco è l’elemento chimico di simbolo Zn e numero atomico 30. È un metallo e le sue abbondanze contribuiscono allo studio della composizione della materia.","lezione-4-3.html"],"zodiaco":["Lo zodiaco astronomico è la fascia del cielo attorno all’eclittica, distinta dai dodici settori convenzionali dei segni astrologici.","lezione-1-6.html"],"zolfo":["Lo zolfo è l’elemento chimico di numero atomico 16 e simbolo S, presente in materiali solidi e in numerose specie gassose planetarie e interstellari.","lezione-3-4.html"],"zona-abitabile":["La zona abitabile circumstellare è la regione di distanze in cui un pianeta potrebbe mantenere acqua liquida in superficie, secondo ipotesi atmosferiche e climatiche dichiarate.","lezione-10-2.html"],"zona-convettiva":["La zona convettiva è una regione stellare dove moti organizzati del plasma contribuiscono in modo dominante al trasporto di energia; nel Sole si trova sotto la fotosfera e sopra la zona radiativa.","lezione-2-3.html"],"zona-radiativa":["La zona radiativa è una regione dell’interno stellare nella quale il trasporto netto di energia avviene prevalentemente per radiazione; nel Sole si trova fra nucleo e zona convettiva.","lezione-2-3.html"]};
